INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---tomorrow-never-dies', 'Playstation', '007 - Tomorrow Never Dies', '1999', 'Action', 'Black Ops Entertainment', '1', 'Third-person shooter', 'Third-person shooter with stealth elements and mission-based gadgets.', 'Complete espionage objectives and eliminate enemies to stop a media mogul.', 'Play as James Bond in this action-packed adaptation of the hit film.', 'Experience 007 - Tomorrow Never Dies for PS1. Master high-tech gadgets and intense combat in this classic cinematic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007-racing', 'Playstation', '007 Racing', '2000', 'Racing', 'Eutechnyx', '2', 'Arcade racing', 'Mission-based vehicular combat and racing with weaponized cars.', 'Complete various combat objectives using iconic Bond vehicles.', 'A unique blend of racing and combat set in the James Bond universe.', '007 Racing brings the world of international espionage to the track. Engage in vehicular warfare with missiles and gadgets across diverse missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007:-the-world-is-not-enough', 'Playstation', '007: The World Is Not Enough', '2000', 'Action', 'Black Ops Entertainment', '1', 'Third-person shooter', 'First-person shooter featuring diverse weaponry and mission objectives.', 'Follow the movie plot to stop a global nuclear threat.', 'Intense FPS action featuring the gadgets and guns of the 007 franchise.', 'Relive the movie in 007: The World Is Not Enough for PlayStation. Fight through detailed levels with authentic Bond weapons and high-stakes missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('100%-star', 'Playstation', '100% Star', '1996', 'Puzzle', 'Psygnosis', '1', 'Arcade puzzle', 'Standard 2D arcade-style shooting and platforming mechanics.', 'Score the highest points possible in various retro-inspired challenges.', 'A collection of classic-style arcade games for high-score hunters.', 'Discover 100% Star, a compilation of arcade thrills. Perfect for players looking for retro gaming challenges and fast-paced gameplay loops.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('101-dalmatians-ii:-patchs-london-adventure', 'Playstation', '101 Dalmatians II: Patch''s London Adventure', '2003', 'Platformer', 'Eidos Interactive', '1', '3D platformer', '2D side-scrolling platformer with puzzle elements for younger players.', 'Rescue the puppies and defeat the evil Cruella de Vil in London.', 'A charming family-friendly adventure based on the Disney sequel.', 'Join Patch in 101 Dalmatians II: Patch''s London Adventure. Navigate London streets in this colorful platformer designed for Disney fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('102-dalmatians---puppies-to-the-rescue', 'Playstation', '102 Dalmatians - Puppies to the Rescue', '2000', 'Platformer', 'Crawfish Interactive', '1', '3D platformer', '3D platformer featuring exploration and item collection.', 'Rescue your puppy siblings from the clutches of Cruella de Vil.', 'An engaging 3D adventure through various London-themed levels.', 'Save the puppies in 102 Dalmatians - Puppies to the Rescue. Explore detailed 3D environments, solve puzzles, and thwart Cruella’s plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1xtreme', 'Playstation', '1Xtreme', '1996', 'Sports', 'Extreme Games', '2', 'Extreme sports', 'Extreme sports racing featuring inline skates, bikes, and skateboards.', 'Race to the finish line while performing stunts and attacking rivals.', 'A gritty, high-energy extreme sports racer with combat elements.', '1Xtreme delivers intense multi-discipline racing. Fight your way to the lead in this foundational extreme sports title for the PlayStation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2xtreme', 'Playstation', '2Xtreme', '1997', 'Sports', 'Extreme Games', '2', 'Extreme sports', 'Evolution of 1Xtreme featuring improved physics and more tricks.', 'Win races and earn points by performing air stunts and combat.', 'Fast-paced extreme sports racing with a focus on aggression and style.', '2Xtreme takes the action further with more tracks and characters. Master the art of combat racing on boards, bikes, and skates.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3d-baseball', 'Playstation', '3D Baseball', '1996', 'Sports', 'Crystal Dynamics', '2', 'Baseball simulation', '3D sports simulation with realistic physics and polygon-based players.', 'Win individual games or guide your team to a World Series victory.', 'An early 3D baseball sim featuring real-time motion and depth.', 'Experience the dawn of 3D sports in 3D Baseball. Featuring realistic perspectives and professional gameplay mechanics for the ultimate fan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3d-lemmings', 'Playstation', '3D Lemmings', '1995', 'Puzzle', 'Psygnosis', '1', 'Puzzle platformer', '3D puzzle-strategy gameplay focusing on environmental navigation.', 'Guide a specific number of Lemmings to the exit of each level.', 'A complex 3D reimagining of the classic Lemmings puzzle formula.', 'Challenge your mind with 3D Lemmings. Navigate intricate vertical environments and manage your team of Lemmings to safety in this brain-teasing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3xtreme', 'Playstation', '3Xtreme', '1999', 'Sports', '989 Studios', '2', 'Extreme sports', 'Advanced extreme sports racing with 3D graphics and complex tricks.', 'Reach the finish line first while maximizing points through stunts.', 'The final evolution of the Xtreme series on PS1 with 3D models.', '3Xtreme brings high-octane racing to life with 3D polygons. Compete across global tracks and prove your dominance in the extreme sports circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('5-star-racing', 'Playstation', '5 Star Racing', '1997', 'Racing', 'Ubi Soft', '2', 'Arcade racing', 'Arcade-style circuit racing with accessible driving mechanics.', 'Win various tournaments and unlock faster, more powerful cars.', 'A straightforward budget racing game focused on speed and simplicity.', '5 Star Racing offers classic arcade driving thrills. Perfect for casual fans looking for quick races and easy-to-learn mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-bugs-life', 'Playstation', 'A Bug''s Life', '1998', 'Platformer', 'Traveller''s Tales', '1', '3D platformer', '3D platformer and exploration game with "shrunken" perspective.', 'Collect grain and items while navigating a giant backyard world.', 'A visually impressive platformer based on the Pixar animated film.', 'Play as Flik in A Bug''s Life for PS1. Explore huge levels from an ant’s perspective, defeat grasshoppers, and save the colony in this Disney classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-train---trains-power-money', 'Playstation', 'A-Train - Trains, Power, Money', '1997', 'Simulation', 'Artdink', '1', 'Strategy simulation', 'City-building and economic management simulation focusing on transit.', 'Build a successful rail network and manage city infrastructure.', 'A deep management sim where you build and run a transportation empire.', 'Master the rails in A-Train. Balance budgets, build massive transit systems, and watch your city grow in this detailed economic simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-combat', 'Playstation', 'Ace Combat', '1995', 'Flight simulator', 'Namco', '1', 'Arcade flight combat', 'Realistic flight combat simulator with various modern fighter jets.', 'Complete air-to-air and air-to-ground missions to win the war.', 'The game that started the legendary Ace Combat flight series.', 'Take to the skies in Ace Combat. Engage in high-speed dogfights and precision bombing missions in this genre-defining flight action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-combat-2-europe', 'Playstation', 'Ace Combat 2 (Europe)', '1997', 'Flight simulator', 'Namco', '1', 'Arcade flight combat', 'Refined flight combat with improved graphics and branching paths.', 'Eliminate enemy forces and achieve air superiority across missions.', 'A high-octane aerial combat sequel with a massive selection of jets.', 'Ace Combat 2 sets the gold standard for PS1 flight games. Experience intense dogfights and a dynamic soundtrack in this fan-favorite sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-combat-2-usa', 'Playstation', 'Ace Combat 2 (USA)', '1997', 'Flight simulator', 'Namco', '1', 'Arcade flight combat', 'Refined flight combat with improved graphics and branching paths.', 'Eliminate enemy forces and achieve air superiority across missions.', 'A high-octane aerial combat sequel with a massive selection of jets.', 'Ace Combat 2 sets the gold standard for PS1 flight games. Experience intense dogfights and a dynamic soundtrack in this fan-favorite sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-combat-3---electrosphere-europe-enfrdeesit', 'Playstation', 'Ace Combat 3 - Electrosphere (Europe) (En,Fr,De,Es,It)', '1999', 'Flight simulator', 'Namco', '1', 'Arcade flight combat', 'Futuristic flight combat with a deep, branching narrative.', 'Protect the world from corporate warfare in a futuristic setting.', 'A cinematic, futuristic flight sim with multiple endings and paths.', 'Ace Combat 3 - Electrosphere features a unique sci-fi aesthetic. Fly advanced jets through a complex story involving corporate espionage and global conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-combat-3---electrosphere-russian-translation', 'Playstation', 'Ace Combat 3 - Electrosphere (Russian Translation)', '1999', 'Flight simulator', 'Namco', '1', 'Arcade flight combat', 'Futuristic flight combat with a deep, branching narrative.', 'Protect the world from corporate warfare in a futuristic setting.', 'A cinematic, futuristic flight sim with multiple endings and paths.', 'Ace Combat 3 - Electrosphere features a unique sci-fi aesthetic. Fly advanced jets through a complex story involving corporate espionage and global conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aces-of-the-air', 'Playstation', 'Aces of the Air', '1997', 'Flight simulator', 'SEGA', '1', 'Arcade flight combat', 'Flight simulator focusing on historical and semi-fictional aircraft.', 'Complete various flight missions including combat and navigation.', 'An accessible flight sim focused on variety and aerial maneuvers.', 'Aces of the Air allows you to pilot classic aircraft. Master the controls and dominate the skies in this mission-based flight experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-bass', 'Playstation', 'Action Bass', '1999', 'Sports', 'Natsume', '1', 'Fishing simulation', 'Fishing simulation with arcade-style mechanics and timing.', 'Catch the largest bass possible within a specific time limit.', 'A fast-paced fishing game focused on action and high scores.', 'Get hooked on Action Bass. Experience the thrill of the catch with responsive controls and multiple fishing spots in this arcade sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-man---operation-extreme', 'Playstation', 'Action Man - Operation Extreme', '2000', 'Action', 'Neverland', '1', 'Action adventure', 'Third-person action-adventure with stealth and combat elements.', 'Stop Dr. X from taking over the world using vehicles and gadgets.', 'An action-packed adventure starring the classic Action Man hero.', 'Join the mission in Action Man - Operation Extreme. Use cool vehicles and weapons to thwart evil in this kid-friendly action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('activision-classics', 'Playstation', 'Activision Classics', '1995', 'Compilation', 'Activision', '2', 'Game compilation', 'Compilation of classic Atari-era arcade and console titles.', 'Achieve high scores in various retro games from the Activision library.', 'A nostalgic collection featuring Pitfall!, River Raid, and more.', 'Activision Classics brings the 2600 era to the PS1. Enjoy pixel-perfect emulations of the games that defined the early days of the industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actua-soccer', 'Playstation', 'Actua Soccer', '1996', 'Sports', 'Gremlin Interactive', '2', 'Soccer simulation', '3D soccer simulation with realistic physics and commentary.', 'Outscore the opponent in standard matches or full tournaments.', 'One of the first 3D soccer games to feature motion-captured players.', 'Actua Soccer provides a realistic 11v11 experience. With professional commentary and 3D graphics, it''s a staple for football fans of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actua-soccer---club-edition', 'Playstation', 'Actua Soccer - Club Edition', '1997', 'Sports', 'Gremlin Interactive', '2', 'Soccer simulation', '3D soccer simulation focusing on specific professional club teams.', 'Lead your favorite club to victory in national and international leagues.', 'A club-focused version of the popular Actua Soccer engine.', 'Actua Soccer - Club Edition lets you play with real rosters and club kits. Experience the atmosphere of the stadium in this focused football sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advan-racing', 'Playstation', 'Advan Racing', '1996', 'Racing', 'Major A', '2', 'Arcade racing', 'Realistic Japanese touring car racing simulation.', 'Win various race series to unlock better parts and new vehicles.', 'A technical racing game focused on the Advan racing circuit.', 'Advan Racing offers a deep look into the world of Japanese motorsports. Fine-tune your car and master challenging tracks in this realistic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advanced-variable-geo', 'Playstation', 'Advanced Variable Geo', '1997', 'Fighting', 'RioSoft', '2', '2D fighting', '2D one-on-one fighting game featuring an all-female cast.', 'Defeat all opponents in a martial arts tournament setting.', 'A classic arcade-style fighter with smooth 2D animation.', 'Advanced Variable Geo brings high-energy fighting action to the PS1. Master unique combos and special moves in this competitive 2D title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advanced-variable-geo-2', 'Playstation', 'Advanced Variable Geo 2', '1998', 'Fighting', 'RioSoft', '2', '2D fighting', 'Refined 2D fighting mechanics with new characters and moves.', 'Win the V.G. tournament by defeating the best fighters in the world.', 'The enhanced sequel to the popular all-female fighting game.', 'Advanced Variable Geo 2 improves on every aspect of the original. Experience fast-paced 2D combat and beautifully drawn character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('agent-armstrong', 'Playstation', 'Agent Armstrong', '1997', 'Action', 'Virgin Interactive', '1', '3D action platformer', 'Side-scrolling 2D action-platformer with a focus on shooting.', 'Infiltrate enemy bases and take down a global terrorist organization.', 'A retro-style action game with high-intensity combat and explosions.', 'Play as Agent Armstrong in this explosive 2D shooter. Navigate through enemy territory and use a massive arsenal to save the day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('agile-warrior-f-111x', 'Playstation', 'Agile Warrior F-111X', '1995', 'Flight simulator', 'Black Ops Entertainment', '1', 'Arcade flight combat', '3D flight combat featuring the F-111X experimental aircraft.', 'Neutralize enemy threats and complete tactical flight objectives.', 'A fast-paced aerial combat game with a focus on experimental tech.', 'Agile Warrior F-111X delivers high-speed jet combat. Use advanced weaponry and stealth to complete dangerous missions in hostile airspace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-combat', 'Playstation', 'Air Combat', '1995', 'Flight simulator', 'Namco', '1', 'Arcade flight combat', '3D flight combat with arcade-style physics and controls.', 'Destroy enemy jets and ground targets across various levels.', 'The foundational title of the Air Combat series (Ace Combat).', 'Experience the origins of a legend with Air Combat. Simple controls and intense dogfights make this an accessible favorite for flight fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-hockey', 'Playstation', 'Air Hockey', '1995', 'Sports', 'Artech Studios', '2', 'Arcade sports', '3D simulation of the classic tabletop air hockey game.', 'Score more goals than your opponent using a mallet and puck.', 'A straightforward and fun digital version of arcade air hockey.', 'Air Hockey brings the arcade table home. Compete against the AI or friends in fast-paced matches with realistic puck physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-race-championship', 'Playstation', 'Air Race Championship', '1996', 'Racing', 'Ubi Soft', '2', 'Arcade racing', 'High-speed aerial racing through obstacle courses.', 'Reach the finish line first while flying through specific gates.', 'A unique racing game where the vehicles are airplanes.', 'Air Race Championship challenges your piloting skills. Navigate tight turns and maintain high speeds to become the champion of the skies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akuji-the-heartless', 'Playstation', 'Akuji the Heartless', '1999', 'Action', 'Crystal Dynamics', '1', '3D action adventure', 'Third-person action-adventure with dark voodoo themes.', 'Reclaim your soul and defeat your enemies in the underworld.', 'A dark, atmospheric adventure featuring combat and exploration.', 'Step into the shadows with Akuji the Heartless. Explore a dark world, use voodoo magic, and fight your way through hell to reclaim your honor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alexi-lalas-international-soccer', 'Playstation', 'Alexi Lalas International Soccer', '1998', 'Sports', 'Software Creations', '2', 'Soccer simulation', '3D soccer simulation featuring the likeness of Alexi Lalas.', 'Win international matches and lead your team to the top of the world.', 'An accessible soccer sim with a focus on international play.', 'Experience world-class football in Alexi Lalas International Soccer. Featuring smooth 3D visuals and realistic international team rosters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alfred-chicken-europe-enfrdeesit', 'Playstation', 'Alfred Chicken (Europe) (En,Fr,De,Es,It)', '1997', 'Platformer', 'Twilight Games', '1', '2D platformer', '2D platformer focusing on puzzle-solving and item collection.', 'Navigate through surreal levels to rescue eggs and defeat Meka-Chicken.', 'A quirky and colorful platformer starring a heroic chicken.', 'Alfred Chicken for PS1 offers classic 2D platforming action. Explore bizarre worlds, solve environmental puzzles, and peck your way to victory in this European favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-resurrection', 'Playstation', 'Alien Resurrection', '2000', 'Shooter', 'Argonaut Games', '1', 'First-person shooter', 'First-person shooter with survival horror elements and dual-stick controls.', 'Survive the Xenomorph outbreak on the Auriga and escape alive.', 'A dark, atmospheric FPS based on the fourth Alien film.', 'Experience true terror in Alien Resurrection. One of the first PS1 games to utilize modern FPS controls, it delivers a chilling survival horror experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-trilogy', 'Playstation', 'Alien Trilogy', '1996', 'Action', 'Psygnosis', '1', 'Survival horror', 'First-person shooter spanning environments from the first three films.', 'Eliminate Xenomorph threats across colonies, prisons, and ships.', 'A high-intensity shooter featuring the iconic Alien franchise lore.', 'Alien Trilogy brings the cinematic thrill of the movies to your console. Fight through infested corridors using pulse rifles and flamethrowers to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-racing', 'Playstation', 'All Star Racing', '1997', 'Racing', 'Ubi Soft', '2', 'Arcade racing', 'Arcade-style circuit racing with various vehicle types.', 'Finish in first place across multiple championship cups.', 'A budget-friendly racing title with simple arcade mechanics.', 'All Star Racing offers fast-paced driving for casual gamers. Choose your car and master various tracks in this straightforward racing competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-racing-2', 'Playstation', 'All Star Racing 2', '1998', 'Racing', 'Ubi Soft', '2', 'Arcade racing', 'Enhanced arcade racing with more tracks and vehicle variety.', 'Outpace rivals and unlock new content in tournament modes.', 'The sequel to All Star Racing featuring improved handling and visuals.', 'All Star Racing 2 expands on the original formula with better graphics and faster gameplay. A solid choice for retro racing fans looking for variety.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-slammin-d-ball', 'Playstation', 'All-Star Slammin'' D-Ball', '1996', 'Sports', 'Beam Software', '2', 'Arcade sports', 'High-speed futuristic dodgeball with special moves and power-ups.', 'Eliminate the opposing team by hitting them with a charged ball.', 'A stylized, anime-inspired take on the classic game of dodgeball.', 'All-Star Slammin'' D-Ball brings explosive energy to the court. Use superhuman abilities and strategic throws to dominate your opponents in this unique sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('allied-general', 'Playstation', 'Allied General', '1998', 'Strategy', 'Hexagon Games', '1', 'Turn-based strategy', 'Turn-based hex-grid strategy focused on World War II.', 'Command Allied forces to victory through historical campaign scenarios.', 'A deep tactical wargame following the Panzer General formula.', 'Allied General puts you in command of the Western Front. Manage resources, units, and strategy in this detailed military simulation for history buffs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alone-in-the-dark---one-eyed-jacks-revenge', 'Playstation', 'Alone in the Dark - One Eyed Jack''s Revenge', '1998', 'Horror', 'Infogrames', '1', 'Survival horror', 'Fixed-camera survival horror with combat and puzzle elements.', 'Explore a haunted mansion to rescue a kidnapped girl and stop a pirate.', 'The second entry in the foundational survival horror series.', 'Alone in the Dark - One Eyed Jack''s Revenge delivers suspense and supernatural mystery. Navigate eerie environments and fight undead foes in this classic horror title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alundra', 'Playstation', 'Alundra', '1997', 'RPG', 'Matrix Software', '1', 'Action RPG', '2D action-adventure with top-down exploration and complex puzzles.', 'Enter the dreams of villagers to save them from a dark nightmare.', 'A critically acclaimed RPG known for its deep story and difficulty.', 'Alundra is a masterpiece of the 2D action-RPG genre. Explore a vast world, solve challenging puzzles, and experience an emotional narrative on the PlayStation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alundra-2:-a-new-legend-begins', 'Playstation', 'Alundra 2: A New Legend Begins', '2000', 'RPG', 'Matrix Software', '1', 'Action RPG', '3D action-RPG with real-time combat and platforming elements.', 'Journey across the sea to stop a pirate conspiracy and save the kingdom.', 'A 3D departure from the original, featuring a new cast and world.', 'Alundra 2: A New Legend Begins offers a lighthearted adventure with 3D graphics. Engage in real-time battles and explore dungeons in this expansive sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-pool', 'Playstation', 'American Pool', '1997', 'Sports', 'Studio 3', '2', 'Pool simulation', 'Physics-based pool simulation with multiple game modes.', 'Sink your balls in the correct order and clear the table to win.', 'A realistic billiards simulation featuring 8-ball and 9-ball.', 'American Pool brings the pool hall home. Practice your shots and compete in tournaments with accurate physics and smooth controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-snap:-rescue-them-2-by-2', 'Playstation', 'Animal Snap: Rescue Them 2 By 2', '1997', 'Puzzle', 'Asmik Ace', '1', 'Puzzle game', 'Tile-matching puzzle gameplay with an animal rescue theme.', 'Match identical animal tiles to clear the board and save them.', 'A family-friendly puzzle game based on the Mahjong solitaire style.', 'Animal Snap: Rescue Them 2 By 2 is a relaxing puzzle experience. Clear the board to rescue pairs of animals in this charming, easy-to-play title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs---ten-pin-alley', 'Playstation', 'Animaniacs - Ten Pin Alley', '1998', 'Sports', 'FarSight Studios', '4', 'Bowling simulation', '3D bowling simulation featuring characters from the Animaniacs show.', 'Score the highest points by knocking down pins in various lanes.', 'A wacky bowling game starring Yakko, Wakko, and Dot.', 'Animaniacs - Ten Pin Alley combines professional bowling mechanics with cartoon humor. Aim for the strike while dealing with the Warner siblings'' antics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animetic-story-game-1---card-captor-sakura-japan-t-en-by-nooneee-v10', 'Playstation', 'Animetic Story Game 1 - Card Captor Sakura (Japan) [T-En by NoOneee v1.0]', '2000', 'Adventure', 'Unknown', '1', 'Visual novel', 'Visual novel and mini-game collection based on the anime series.', 'Follow the story of Sakura Kinomoto and capture the Clow Cards.', 'A faithful adaptation of the beloved magical girl anime.', 'Animetic Story Game 1 - Card Captor Sakura lets fans play through the anime''s plot. Feature-rich with cutscenes and mini-games, now accessible in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ape-escape', 'Playstation', 'Ape Escape', '1999', 'Platformer', 'Japan Studio', '1', '3D platformer', '3D platformer featuring gadget usage and monkey-catching mechanics.', 'Capture all the escaped monkeys using various high-tech tools.', 'A revolutionary title that required the first DualShock controller.', 'Ape Escape is a landmark PlayStation title. Use the analog sticks to swing nets and drive vehicles as you track down mischievous monkeys across time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('apocalypse', 'Playstation', 'Apocalypse', '1998', 'Action', 'Neversoft', '1', 'Third-person shooter', 'Third-person shooter featuring the likeness and voice of Bruce Willis.', 'Stop the Four Horsemen of the Apocalypse from destroying the world.', 'An explosive action game with cinematic flair and fast combat.', 'Apocalypse delivers non-stop shooting action. Play as Bruce Willis in this high-octane adventure filled with big guns and massive explosions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aqua-gt', 'Playstation', 'Aqua GT', '2000', 'Racing', 'Digital Illusions CE', '2', 'Arcade racing', 'Top-down vehicle-based action and racing in aquatic environments.', 'Complete missions involving combat and delivery across water-ways.', 'An aquatic take on the classic top-down "GTA" style gameplay.', 'Aqua GT combines high-speed boat racing with mission-based objectives. Navigate through water-logged environments and outrun your enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aquanauts-holiday', 'Playstation', 'Aquanaut''s Holiday', '1999', 'Simulation', 'Artdink', '1', 'Underwater exploration', 'Non-linear underwater exploration and scuba simulation.', 'Explore the ocean depths to discover marine life and hidden ruins.', 'A peaceful and atmospheric diving simulator for the PS1.', 'Aquanaut''s Holiday offers a serene escape. Dive into a vast underwater world, interact with sea creatures, and enjoy the tranquil beauty of the deep sea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arc-the-lad-collection---arc-arena---monster-tournament', 'Playstation', 'Arc the Lad Collection - Arc Arena - Monster Tournament', '1999', 'Strategy', 'GungHo', '2', 'Tactical RPG', 'Turn-based tactical RPG with a focus on monster recruitment.', 'Defeat opponents in an arena setting using trained monsters.', 'A dedicated monster combat expansion for the Arc the Lad series.', 'Arc Arena - Monster Tournament allows you to use your monsters from the main games in competitive battles. Perfect for fans of tactical squad building.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcade-party-pak', 'Playstation', 'Arcade Party Pak', '1997', 'Compilation', 'Eurocom', '4', 'Arcade compilation', 'Compilation of classic Midway arcade titles in one disc.', 'Achieve high scores and experience legendary arcade hits.', 'A collection featuring Rampage, Gauntlet, and Defender.', 'Arcade Party Pak brings the golden age of arcades to your living room. Enjoy pixel-perfect ports of iconic multiplayer games from the 80s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcades-greatest-hits---the-atari-collection-1', 'Playstation', 'Arcade''s Greatest Hits - The Atari Collection 1', '1997', 'Compilation', 'Digital Eclipse', '2', 'Arcade compilation', 'Collection of foundational Atari arcade classics.', 'Master the retro mechanics of the games that started it all.', 'Features Asteroids, Centipede, Missile Command, and more.', 'Arcade''s Greatest Hits - The Atari Collection 1 is a trip down memory lane. Experience the early days of gaming with these perfectly preserved classics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcades-greatest-hits---the-atari-collection-2', 'Playstation', 'Arcade''s Greatest Hits - The Atari Collection 2', '1998', 'Compilation', 'Digital Eclipse', '2', 'Arcade compilation', 'Second volume of Atari''s most influential arcade games.', 'Score high and survive the challenges of classic arcade logic.', 'Includes Gauntlet, Marble Madness, Paperboy, and RoadBlasters.', 'Arcade''s Greatest Hits - The Atari Collection 2 offers even more retro variety. Play the games that defined arcade culture throughout the 80s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcades-greatest-hits---the-midway-collection-2', 'Playstation', 'Arcade''s Greatest Hits - The Midway Collection 2', '1999', 'Compilation', 'Digital Eclipse', '2', 'Arcade compilation', 'Collection of Midway''s high-action arcade hits from the early 90s.', 'Defeat waves of enemies or set records in various genres.', 'Features Mortal Kombat 2, Mortal Kombat 3, and Spy Hunter.', 'Arcade''s Greatest Hits - The Midway Collection 2 is packed with adrenaline. Fight, drive, and shoot through some of the biggest names in arcade history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('archer-macleans-super-dropzone', 'Playstation', 'Archer Maclean''s Super Dropzone', '1994', 'Shooter', 'Eurocom', '1', 'Fixed shooter', 'Side-scrolling 2D shooter with fast-paced rescue mechanics.', 'Save survivors while fending off waves of alien invaders.', 'A frantic, modern reimagining of the classic Dropzone formula.', 'Archer Maclean''s Super Dropzone offers non-stop shooting action. Navigate dangerous landscapes and protect your people in this intense arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('area-51', 'Playstation', 'Area 51', '1996', 'Shooter', 'Mesa Logic', '2', 'Light gun shooter', 'Light-gun shooter ported from the arcade (supports controller).', 'Shoot your way through a secret government facility overrun by aliens.', 'A legendary sci-fi shooter known for its pre-rendered graphics.', 'Area 51 brings the arcade rail-shooter experience home. Blast through waves of aliens and uncover the secrets of the world''s most famous base.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arkanoid-r-2000', 'Playstation', 'Arkanoid R 2000', '1997', 'Action', 'Taito', '2', 'Arcade action', 'Modernized brick-breaking arcade action with new power-ups.', 'Clear all blocks in each level to advance to the next stage.', 'A sleek 32-bit update to the classic Arkanoid formula.', 'Arkanoid R 2000 revitalizes the classic paddle-and-ball gameplay. With updated visuals and new challenges, it''s the ultimate version of a gaming staple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armed-fighter', 'Playstation', 'Armed Fighter', '1997', 'Action', 'Natsume', '2', 'Arcade action', '3D weapon-based fighting game with a diverse roster.', 'Defeat every challenger to become the ultimate armed champion.', 'A technical 3D fighter focused on melee and weapon combat.', 'Armed Fighter offers intense one-on-one battles. Master different fighting styles and weapon types to dominate the arena in this 3D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armored-core-usa', 'Playstation', 'Armored Core (USA)', '1997', 'Action', 'FromSoftware', '1', 'Mech action', 'Third-person mecha combat with deep customization and building.', 'Complete mercenary missions to earn money and upgrade your mech.', 'The original title of the premier mecha-simulation series.', 'Armored Core lets you build the ultimate fighting machine. Customize every part of your robot and take on dangerous missions in a dark future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armored-core:-master-of-arena-usa-disc-1', 'Playstation', 'Armored Core: Master of Arena (USA) (Disc 1)', '2000', 'Action', 'FromSoftware', '1', 'Mech action', 'Advanced mecha combat focusing on high-level arena duels.', 'Climb the ranks of the arena and defeat the world''s best pilots.', 'A standalone expansion focusing on 1v1 mech combat.', 'Armored Core: Master of Arena (Disc 1) hones in on the competitive side of the series. Battle the most difficult AI pilots ever created.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armored-core:-master-of-arena-usa-disc-2', 'Playstation', 'Armored Core: Master of Arena (USA) (Disc 2)', '2000', 'Action', 'FromSoftware', '1', 'Mech action', 'Additional missions and data for the Master of Arena expansion.', 'Unlock secret parts and complete high-difficulty side missions.', 'The second half of the Master of Arena experience.', 'Armored Core: Master of Arena (Disc 2) provides more content for hardcore fans, including extra parts and the ability to import your previous saves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armored-core:-project-phantasma', 'Playstation', 'Armored Core: Project Phantasma', '1997', 'Action', 'FromSoftware', '1', 'Mech action', 'Tactical mecha combat featuring a self-contained story campaign.', 'Uncover a conspiracy involving a mysterious giant mech project.', 'A focused expansion that adds new parts and a new narrative.', 'Armored Core: Project Phantasma expands the world of AC. Experience a new story and add even more specialized weapons to your arsenal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armorines:-project-swarm', 'Playstation', 'Armorines: Project S.W.A.R.M.', '1998', 'Shooter', 'Sony Interactive Studios', '1', 'Third-person shooter', 'First-person shooter based on the comic book series.', 'Stop an alien insectoid invasion from wiping out humanity.', 'A dark, sci-fi FPS featuring varied weapons and environments.', 'Armorines: Project S.W.A.R.M. pits you against swarms of alien bugs. Use high-tech armor and heavy weaponry to save the planet in this intense shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---world-war', 'Playstation', 'Army Men - World War', '1998', 'Action', '3DO', '1', 'Third-person action', 'Third-person shooter focusing on plastic soldier infantry combat.', 'Lead your green soldiers to victory against the tan army in WW2.', 'A gritty, war-focused entry in the popular Army Men series.', 'Army Men - World War takes the plastic soldiers to the front lines. Engage in mission-based combat across trenches and beaches in this unique war sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-3d', 'Playstation', 'Army Men 3D', '1998', 'Action', '3DO', '2', 'Third-person action', '3D action game with vehicle segments and infantry missions.', 'Complete objectives to thwart the tan army''s global plans.', 'The first fully 3D entry in the Army Men franchise.', 'Army Men 3D brings the toy chest to life. Experience the war from a soldier''s perspective in various 3D environments filled with plastic carnage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-air-attack', 'Playstation', 'Army Men Air Attack', '1999', 'Action', '3DO', '1', 'Third-person helicopter shooter', 'Helicopter-based combat and rescue missions in 3D environments.', 'Complete air-support missions and defeat tan army aerial forces.', 'Fly plastic military helicopters in this toy-themed flight action game.', 'Army Men Air Attack brings aerial combat to the plastic battlefield. Pilot various choppers to protect Green territory and destroy Tan bases in this classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-air-attack-2', 'Playstation', 'Army Men Air Attack 2', '2000', 'Action', '3DO', '1', 'Third-person helicopter shooter', 'Mission-based aerial combat with multiple flyable helicopters.', 'Thwart the plans of Baron von Beige across diverse backyard maps.', 'An enhanced sequel featuring more choppers and bigger plastic wars.', 'Army Men Air Attack 2 elevates the series with better graphics and new weapons. Experience high-flying action in a world where everything is toy-sized.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-sarges-heroes', 'Playstation', 'Army Men Sarges Heroes', '1999', 'Action', '3DO', '2', 'Third-person shooter', 'Third-person shooter with a focus on mission-based infantry combat.', 'Lead Sarge and his squad to rescue commandos and stop General Plastro.', 'A character-driven action game starring the iconic Green Army leader.', 'Army Men Sarge''s Heroes is a definitive 3D action title. Battle through massive real-world environments like kitchens and gardens to save your plastic comrades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-sarges-heroes-2', 'Playstation', 'Army Men Sarges Heroes 2', '2000', 'Action', '3DO', '2', 'Third-person shooter', 'Refined third-person shooting with new characters and environments.', 'Prevent the Tan Army from launching a devastating new weapon.', 'The direct sequel to Sarge''s Heroes with improved controls and visuals.', 'Sarge returns in Army Men Sarge''s Heroes 2. Featuring more "real world" interactive levels and a deep story, it''s a must-play for fans of plastic soldier combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-world-war-final-front', 'Playstation', 'Army Men World War Final Front', '2001', 'Action', '3DO', '1', 'Third-person shooter', 'Tactical third-person shooting with a focus on global war missions.', 'Execute strategic strikes to end the war between Green and Tan forces.', 'A more realistic take on the Army Men series focusing on military tactics.', 'Army Men World War Final Front offers intense infantry missions. Navigate dangerous battlefields and use authentic-style weaponry in this plastic war simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-world-war-land-sea-and-air', 'Playstation', 'Army Men World War Land, Sea And Air', '2000', 'Action', '3DO', '1', 'Third-person shooter', 'Combined arms combat featuring land, sea, and air operations.', 'Coordinate multi-front attacks to dismantle the Tan Army''s defenses.', 'A diverse action game covering various theaters of plastic warfare.', 'Experience the breadth of combat in Army Men World War Land, Sea and Air. From boat missions to ground assaults, it''s the ultimate toy soldier experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-world-war-team-assault', 'Playstation', 'Army Men World War Team Assault', '2001', 'Action', '3DO', '2', 'Third-person shooter', 'Squad-based third-person shooter with cooperative-style missions.', 'Lead a specialized team to infiltrate and destroy key Tan installations.', 'Focuses on small-unit tactics and high-intensity combat encounters.', 'Army Men World War Team Assault emphasizes coordination and firepower. Take control of a specialized squad and turn the tide of the plastic war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men:-green-rogue', 'Playstation', 'Army Men: Green Rogue', '2001', 'Action', '3DO', '1', 'Third-person action', '"Run and gun" style arcade shooter from a fixed perspective.', 'Survive waves of Tan enemies as a lone Green commando rogue.', 'A fast-paced, arcade-centric spin-off of the main Army Men series.', 'Army Men: Green Rogue offers non-stop shooting action. Battle through hordes of enemies in this frantic, top-down perspective shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arthur!-ready-to-race', 'Playstation', 'Arthur! Ready to Race', '2000', 'Racing', 'Creative Capers', '2', 'Arcade kart racing', 'Kart-style racing with characters from the Arthur TV show.', 'Win races and collect items to help Arthur build his ultimate racer.', 'A family-friendly racing game designed for younger players.', 'Arthur! Ready to Race is a charming adventure for kids. Join Arthur and his friends in various mini-games and races across Elwood City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assault---retribution', 'Playstation', 'Assault - Retribution', '1998', 'Shooter', 'Psygnosis', '2', 'Top-down shooter', 'Third-person sci-fi shooter featuring two playable protagonists.', 'Repel an alien invasion and protect human colonies from extinction.', 'A high-action shooter with a dark, futuristic aesthetic.', 'Assault - Retribution delivers intense alien-blasting action. Choose your soldier and fight through hordes of extra-terrestrial threats in this 3D shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assault-rigs', 'Playstation', 'Assault Rigs', '1996', 'Racing', 'Psygnosis', '2', 'Futuristic racing', 'Vehicular combat in futuristic, arena-style environments.', 'Navigate digital mazes and destroy enemy tanks to reach the exit.', 'A stylized tank combat game with a "cyber" aesthetic.', 'Assault Rigs pits you against high-tech security systems in a virtual world. Master tank maneuvers and firepower to conquer challenging levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-europe-enfrdenl', 'Playstation', 'Asterix (Europe) (En,Fr,De,Nl)', '1996', 'Platformer', 'Core Design', '1', '2D platformer', '2D side-scrolling platformer based on the famous comic series.', 'Travel through various provinces to prove Gaulish superiority to Caesar.', 'A colorful and challenging platformer featuring Asterix and Dogmatix.', 'Join the indomitable Gauls in Asterix. Battle Romans and explore vibrant levels across Europe in this faithful adaptation of the comic books.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-europe-enfresit', 'Playstation', 'Asterix (Europe) (En,Fr,Es,It)', '1996', 'Platformer', 'Core Design', '1', '2D platformer', '2D side-scrolling platformer based on the famous comic series.', 'Travel through various provinces to prove Gaulish superiority to Caesar.', 'A colorful and challenging platformer featuring Asterix and Dogmatix.', 'Join the indomitable Gauls in Asterix. Battle Romans and explore vibrant levels across Europe in this faithful adaptation of the comic books.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-&-obelix-take-on-caesar-europe', 'Playstation', 'Asterix & Obelix Take on Caesar (Europe)', '1999', 'Adventure', 'Infogrames', '2', 'Action adventure', '3D action-adventure based on the live-action movie.', 'Free the kidnapped druid Getafix and stop the Roman occupation.', 'An action-packed tie-in featuring the likeness of the movie actors.', 'Asterix & Obelix Take on Caesar brings the big-screen action home. Punch Romans and solve puzzles in this cinematic journey through Gaul.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix:-mega-madness', 'Playstation', 'Asterix: Mega Madness', '2002', 'Party', 'Twilight Games', '4', 'Party minigames', 'Collection of mini-games and party challenges for multiple players.', 'Compete in various Roman-themed contests to win the tournament.', 'A humorous party game featuring the beloved characters of Gaul.', 'Asterix: Mega Madness is a blast for the whole family. Compete in wild challenges and prove you are the strongest Gaul in the village.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asteroids', 'Playstation', 'Asteroids', '1998', 'Shooter', 'Digital Eclipse', '2', 'Arcade shooter', 'Modernized 3D update of the classic brick-breaking arcade game.', 'Destroy asteroids and UFOs while avoiding collisions and fire.', 'A 32-bit reimagining of the foundational vector arcade classic.', 'Asteroids for PS1 brings the classic space shooter into the third dimension. Experience updated graphics, bosses, and intense arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-anniversary-edition', 'Playstation', 'Atari Anniversary Edition', '2001', 'Compilation', 'Digital Eclipse', '2', 'Retro compilation', 'Emulated collection of classic Atari arcade and console hits.', 'Relive the history of gaming by achieving high scores in retro titles.', 'Features 12 legendary games including Centipede and Missile Command.', 'Atari Anniversary Edition is the ultimate tribute to the golden age. Play pixel-perfect versions of the games that started it all.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('attack-of-the-saucerman', 'Playstation', 'Attack of the Saucerman', '1999', 'Action', 'Psygnosis', '1', 'Third-person action', 'Third-person action-adventure featuring an alien protagonist.', 'Help the alien hero escape from Earth while causing chaotic destruction.', 'A humorous and quirky adventure with a unique sci-fi theme.', 'Attack of the Saucerman offers a fun perspective on the alien invasion genre. Explore human environments and use gadgets to stay one step ahead of the Men in Black.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv-mania', 'Playstation', 'ATV Mania', '2000', 'Racing', 'Skyworks Technologies', '2', 'Arcade racing', '3D off-road racing featuring All-Terrain Vehicles.', 'Win races across rugged environments and unlock new upgrades.', 'A budget-friendly ATV racer with arcade physics and simple fun.', 'ATV Mania provides fast-paced off-road thrills. Navigate dirt tracks and master the jumps in this accessible racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv-racers', 'Playstation', 'ATV Racers', '2001', 'Racing', 'Westwood Studios', '2', 'Arcade racing', 'High-speed quad bike racing across diverse outdoor tracks.', 'Compete in championships to become the top ATV racer in the circuit.', 'A straightforward racing game focused on quad bike competition.', 'ATV Racers offers competitive off-road action. Choose your rider, customize your quad, and dominate the mud in this arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('austin-powers-pinball-usa', 'Playstation', 'Austin Powers Pinball (USA)', '2001', 'Pinball', 'Tarantula Studios', '4', 'Pinball simulation', '2D pinball simulation themed after the Austin Powers films.', 'Score points by hitting targets and completing movie-themed missions.', 'A groovy pinball experience filled with clips and humor from the movie.', 'Austin Powers Pinball brings the International Man of Mystery to the silver ball. Enjoy "shagadelic" table designs and hilarious soundbites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('auto-destruct', 'Playstation', 'Auto Destruct', '1998', 'Action', 'Neversoft', '2', 'Third-person vehicular combat', 'Mission-based vehicular combat set in large open environments.', 'Carry out demolition and combat missions to stop a global cult.', 'A high-octane mix of driving and shooting with explosive physics.', 'Auto Destruct puts you behind the wheel of a weaponized car. Engage in urban warfare and complete high-stakes objectives in this action-heavy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('autobahn-raser-2', 'Playstation', 'Autobahn Raser 2', '1998', 'Racing', 'Davilex', '2', 'Arcade racing', 'High-speed illegal street racing through German highways.', 'Outrun the police and reach the finish line first in urban settings.', 'A fast-paced European racing game focused on high-speed chases.', 'Autobahn Raser 2 delivers the thrill of the German highway. Weave through traffic and upgrade your cars in this intense street racing sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('azure-dreams-usa', 'Playstation', 'Azure Dreams (USA)', '1997', 'RPG', 'Koei', '1', 'Roguelike RPG', 'Hybrid roguelike RPG with monster taming and town building.', 'Climb the randomly generated Monsbaiya Tower to find treasure.', 'A unique cult-classic featuring deep RPG mechanics and dating sim elements.', 'Azure Dreams is a deep and rewarding experience. Hatch monsters, customize your home, and explore an ever-changing tower in this PS1 gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baby-felix-tennis', 'Playstation', 'Baby Felix Tennis', '1997', 'Sports', 'Hudson Soft', '2', 'Arcade tennis', 'Arcade-style tennis game featuring characters from the Baby Felix cartoon.', 'Defeat opponents in various themed tournaments to win the cup.', 'A bright and accessible tennis game for younger audiences.', 'Baby Felix Tennis offers simple, fun sports action. Play as your favorite characters and master the court in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakumatsu-roman---gekka-no-kenshi-japan', 'Playstation', 'Bakumatsu Roman - Gekka no Kenshi (Japan)', '1997', 'Fighting', 'SNK', '2', '2D fighting', '2D weapon-based fighting game with a historical Japanese setting.', 'Defeat opponents in a duel to the death during the Bakumatsu era.', 'A beautiful and technical fighter known as "The Last Blade."', 'Experience the artistry of Bakumatsu Roman - Gekka no Kenshi. With stunning sprites and deep combat mechanics, it''s a pinnacle of 2D fighting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakusou-kyoudai-lets-&-go!!-eternal-wings-japan', 'Playstation', 'Bakusou Kyoudai Let''s & Go!! Eternal Wings (Japan)', '1999', 'Racing', 'XING', '2', 'Anime arcade racing', 'Mini-4WD racing simulation based on the popular anime series.', 'Customize your car with parts and win the high-speed racing circuit.', 'A niche racing sim focused on the "Let''s & Go!!" hobbyist world.', 'Bakusou Kyoudai Let''s & Go!! Eternal Wings brings model car racing to life. Fine-tune your machine for maximum speed in this anime-inspired title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballerburg:-castle-chaos', 'Playstation', 'Ballerburg: Castle Chaos', '1997', 'Strategy', 'Radical Entertainment', '2', 'Real-time strategy', 'Artillery-based strategy and castle defense game.', 'Destroy the enemy castle using catapults while defending your own.', 'A modern 3D take on the classic "Artillery" or "Scorched Earth" genre.', 'Ballerburg: Castle Chaos is a game of physics and strategy. Aim your shots carefully and manage your kingdom to outlast your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballistic', 'Playstation', 'Ballistic', '1999', 'Shooter', 'Magenta Software', '2', 'First-person shooter', 'High-speed puzzle game focusing on matching colored spheres.', 'Clear the board by shooting colored balls into a moving chain.', 'A frantic and addictive puzzle game similar to the "Zuma" style.', 'Ballistic challenges your reflexes and planning. Prevent the chain of balls from reaching the center in this fast-paced arcade puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie---explorer', 'Playstation', 'Barbie - Explorer', '1999', 'Adventure', 'Runecraft', '1', 'Action adventure', 'Third-person action-adventure featuring exploration and puzzles.', 'Find four ancient treasures hidden across global environments.', 'Barbie takes on a "Tomb Raider" style adventure in this fun title.', 'Barbie - Explorer is an action-packed journey through jungles and ruins. Solve puzzles and navigate obstacles to find the missing artifacts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie---gotta-have-games', 'Playstation', 'Barbie - Gotta Have Games', '2001', 'Compilation', 'Runecraft', '2', 'Minigame compilation', 'Collection of various mini-games and social activities.', 'Complete diverse tasks and games to earn points and rewards.', 'A variety-focused title for younger fans of the Barbie franchise.', 'Barbie - Gotta Have Games offers a wide range of fun activities. From music to sports, there''s always something new to do in Barbie''s world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie---race-&-ride-usa', 'Playstation', 'Barbie - Race & Ride (USA)', '2000', 'Racing', 'Runecraft', '1', 'Arcade racing', 'Equestrian simulation featuring horse riding and grooming.', 'Train your horse and compete in various riding events and trails.', 'A peaceful game focused on the bond between a rider and her horse.', 'Barbie - Race & Ride is perfect for horse lovers. Explore secret trails, care for your pony, and participate in friendly competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie---super-sports', 'Playstation', 'Barbie - Super Sports', '1999', 'Sports', 'Runecraft', '2', 'Arcade sports', 'Sports compilation featuring extreme sports like skating and surfing.', 'Win gold medals in various sports events to unlock new gear.', 'A high-energy sports game starring Barbie and her friends.', 'Barbie - Super Sports brings the competition to the PS1. Master snowboarding and inline skating in this fun, active sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baroque---yuganda-mousou-japan', 'Playstation', 'Baroque - Yuganda Mousou (Japan)', '1998', 'RPG', 'Sting', '1', 'Survival RPG', 'First-person roguelike dungeon crawler with a surreal dark theme.', 'Explore the Neuro Tower to find the "Absolute Being" and fix the world.', 'A dark, atmospheric cult-classic with deep lore and bizarre design.', 'Baroque - Yuganda Mousou offers a hauntingly unique experience. Navigate twisted floors and experience a story of sin and redemption.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baroque-syndrome-japan', 'Playstation', 'Baroque Syndrome (Japan)', '1998', 'Horror', 'Sting', '1', 'Psychological horror', 'Visual novel and prequel to the dark fantasy world of Baroque.', 'Investigate mysterious cases involving "Baroque" delusions in the city.', 'A narrative-heavy investigation game with a dark, psychological tone.', 'Baroque Syndrome expands the lore of the series. Uncover the secrets behind the distortion of reality in this atmospheric visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-fishing-game---lake-masters', 'Playstation', 'Bass Fishing Game - Lake Masters', '1998', 'Sports', 'Victor Interactive', '1', 'Fishing simulation', 'Realistic fishing simulation with various lures and lake environments.', 'Catch the heaviest bass to win professional tournaments.', 'A technical fishing sim focused on precision and patience.', 'Bass Fishing Game - Lake Masters offers a deep angling experience. Master different lures and weather conditions to become the ultimate lake master on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-rise', 'Playstation', 'Bass Rise', '1999', 'Sports', 'Konami', '1', 'Fishing simulation', 'Arcade-style fishing with high-energy strikes and reeling action.', 'Hook and land trophy-sized bass across multiple scenic locations.', 'A fast-paced fishing game with a focus on excitement and big catches.', 'Bass Rise delivers high-octane fishing thrills. Experience the rush of a big bite and the struggle to land massive bass in this vibrant arcade sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-&-robin', 'Playstation', 'Batman & Robin', '1998', 'Action', 'Probe Entertainment', '1', 'Third-person action', 'Third-person action-adventure with driving and combat elements.', 'Protect Gotham City by solving puzzles and fighting iconic villains.', 'An ambitious open-world adventure based on the cinematic film.', 'Batman & Robin for PS1 lets you patrol Gotham in the Batmobile. Switch between characters to solve crimes and stop Mr. Freeze''s icy plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-beyond:-return-of-the-joker', 'Playstation', 'Batman Beyond: Return of the Joker', '2000', 'Action', 'Kemco', '1', 'Third-person action', '2D side-scrolling beat ''em up featuring futuristic gadgets.', 'Fight through the Jokerz gang to stop the clown prince''s return.', 'A classic brawler based on the hit animated movie.', 'Batman Beyond: Return of the Joker brings futuristic combat to your console. Use powerful suits and gadgets to defeat the Jokerz in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-forever:-the-arcade-game', 'Playstation', 'Batman Forever: The Arcade Game', '1996', 'Fighting', 'Probe Entertainment', '2', '2D arcade fighting', '2.5D side-scrolling beat ''em up with digitized character sprites.', 'Fight through waves of thugs and bosses from the Batman Forever film.', 'A fast-paced arcade brawler with special moves and hidden secrets.', 'Batman Forever: The Arcade Game offers chaotic fighting action. Choose Batman or Robin and unleash massive combos in this over-the-top cinematic adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman:-gotham-city-racer', 'Playstation', 'Batman: Gotham City Racer', '2001', 'Racing', 'Sinister Games', '1', 'Arcade racing', 'Vehicular combat and racing set in the streets of Gotham.', 'Complete missions and take down criminals using weaponized vehicles.', 'A mission-based driving game featuring the Batmobile.', 'Batman: Gotham City Racer combines high-speed chases with heroic action. Explore Gotham behind the wheel and bring justice to the city''s dark streets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-arena-toshinden', 'Playstation', 'Battle Arena Toshinden', '1995', 'Fighting', 'Tamsoft', '2', '3D fighting', '3D weapon-based fighting game with a full range of movement.', 'Defeat all opponents in a high-stakes martial arts tournament.', 'A landmark 3D fighter that helped define the PlayStation era.', 'Battle Arena Toshinden features intense sword-based combat. Master unique special moves and 3D sidestepping in this foundational fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-arena-toshinden-2', 'Playstation', 'Battle Arena Toshinden 2', '1996', 'Fighting', 'Tamsoft', '2', '3D fighting', 'Enhanced 3D weapon-based fighting with faster gameplay and new characters.', 'Prove your strength in the second secret Toshinden tournament.', 'The refined sequel to the original hit 3D weapon fighter.', 'Battle Arena Toshinden 2 offers smoother animations and more aggressive combat. Experience the evolution of the series with new challengers and deadly combos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-arena-toshinden-2-plus', 'Playstation', 'Battle Arena Toshinden 2 Plus', '1996', 'Fighting', 'Tamsoft', '2', '3D fighting', 'Updated version of the second title with balance tweaks and extra features.', 'Dominate the arena with refined moves and hidden characters.', 'A specialized update of the second Toshinden for hardcore fans.', 'Battle Arena Toshinden 2 Plus brings professional balance and secret unlocks to the classic 3D fighter. Perfect for competitive players seeking the best version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-arena-toshinden-3', 'Playstation', 'Battle Arena Toshinden 3', '1997', 'Fighting', 'Tamsoft', '2', '3D fighting', 'High-speed 3D weapon fighting with a massive roster and branching paths.', 'Win the final battle of the third tournament to uncover the truth.', 'A content-rich sequel with dozens of characters and fighting styles.', 'Battle Arena Toshinden 3 pushes the PS1 to its limits with fast frame rates and 32 playable fighters. Engage in the most expansive Toshinden battle yet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-arena-toshinden-4', 'Playstation', 'Battle Arena Toshinden 4', '1999', 'Fighting', 'Tamsoft', '2', '3D fighting', 'Team-based 3D weapon combat with a new generation of fighters.', 'Lead your team to victory in a series of strategic duels.', 'The final PS1 entry featuring team mechanics and updated visuals.', 'Battle Arena Toshinden 4 refreshes the series with a focus on team play. Master new character designs and fast-paced weapon combat in this finale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-hunter', 'Playstation', 'Battle Hunter', '2000', 'RPG', 'Hudson Soft', '1', 'Tactical RPG', 'Turn-based tactical RPG with grid-based movement and item hunting.', 'Compete against other hunters to find rare items in dangerous ruins.', 'A unique blend of strategy and treasure hunting in a sci-fi world.', 'Battle Hunter is a hidden gem of tactical strategy. Outsmart rivals and survive randomly generated dungeons to become the world''s top hunter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlestations', 'Playstation', 'Battlestations', '1997', 'Action', 'Imagitec Design', '1', 'Top-down shooter', 'Real-time naval combat strategy featuring ships, subs, and aircraft.', 'Eliminate enemy fleets and capture strategic island bases.', 'A fast-paced naval warfare game with both action and strategy.', 'Battlestations pits you against the world''s greatest navies. Manage your fleet and engage in explosive sea-to-air battles in this intense military sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletanx:-global-assault', 'Playstation', 'BattleTanx: Global Assault', '1999', 'Action', 'LucasArts', '2', 'Third-person vehicular combat', 'Mission-based vehicular tank combat with destructible environments.', 'Lead the resistance to reclaim Earth''s cities from the tank invaders.', 'High-octane tank warfare across global landmarks.', 'BattleTanx: Global Assault is all about explosive destruction. Use massive firepower to level entire cities and defeat enemy tank squads in this action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beast-wars:-transformers', 'Playstation', 'Beast Wars: Transformers', '1997', 'Action', 'SingleTrac', '1', 'Action adventure', '3D fighting game featuring transforming robot-animals.', 'Win the war between Maximals and Predacons on a prehistoric world.', 'A fighter based on the popular CGI animated Transformers series.', 'Beast Wars: Transformers brings the hit show to the PS1. Transform between beast and robot modes mid-battle to gain the upper hand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beat-mania---the-sound-of-tokyo-japan', 'Playstation', 'Beat Mania - The Sound of Tokyo (Japan)', '1998', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based music game focusing on DJ scratching and timing.', 'Hit the notes in time with the music to keep the crowd dancing.', 'A Tokyo-themed expansion of the revolutionary rhythm series.', 'Beat Mania - The Sound of Tokyo lets you live the life of a club DJ. Master the turntable mechanics and experience the urban sounds of Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania---best-hits-japan', 'Playstation', 'BeatMania - Best Hits (Japan)', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Compilation of the most popular tracks from the BeatMania series.', 'Achieve perfect timing on a collection of legendary rhythm tracks.', 'A "best-of" collection featuring fan-favorite music and levels.', 'BeatMania - Best Hits brings together the finest tracks in the franchise. Test your reflexes with a curated list of hits that defined the rhythm genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-europe', 'Playstation', 'BeatMania (Europe)', '1998', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based music game using a specialized 5-button controller.', 'Follow the beat to perform various electronic and pop tracks.', 'The European debut of the world''s most influential DJ sim.', 'BeatMania brings the Japanese arcade phenomenon to Europe. Experience the original rhythm gameplay that paved the way for modern music games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-japan', 'Playstation', 'BeatMania (Japan)', '1997', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based music game using a specialized 5-button controller.', 'Follow the beat to perform various electronic and pop tracks.', 'The foundational rhythm game that started the DJ simulation craze.', 'BeatMania is the pioneer of music gaming. Spin the virtual turntable and hit the keys to create your own club atmosphere at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-6th-mix-+-core-remix-japan', 'Playstation', 'BeatMania 6th Mix + Core Remix (Japan)', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Advanced rhythm gameplay featuring a massive electronic soundtrack.', 'Master the most complex tracks and remixes in the series history.', 'A massive compilation for the most dedicated BeatMania players.', 'BeatMania 6th Mix + Core Remix offers the ultimate challenge. Featuring a vast library of technical tracks, it’s a masterclass in rhythm gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-append-3rd-mix-japan', 'Playstation', 'BeatMania Append 3rd Mix (Japan)', '1998', 'Music', 'Konami', '2', 'Rhythm game', 'Expansion disc featuring new tracks and updated visuals for the base game.', 'Clear the new "3rd Mix" tracklist with high accuracy.', 'The third major update for the BeatMania home experience.', 'BeatMania Append 3rd Mix adds even more variety to your collection. Expand your playlist with new genres and challenging beat patterns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-append-4th-mix---the-beat-goes-on-japan', 'Playstation', 'BeatMania Append 4th Mix - The Beat Goes On (Japan)', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Expansion disc introducing high-energy tracks and new difficulty levels.', 'Conquer the "4th Mix" songs and prove your DJ skills.', 'A high-energy expansion focused on the evolving club music scene.', 'BeatMania Append 4th Mix - The Beat Goes On keeps the rhythm alive. Integrate new songs into your game and master the latest dance floor hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-append-5th-mix---time-to-get-down-japan', 'Playstation', 'BeatMania Append 5th Mix - Time to Get Down (Japan)', '2000', 'Music', 'Konami', '2', 'Rhythm game', 'Expansion disc featuring late-90s electronic and dance music.', 'Reach the top of the leaderboards with perfect timing on new tracks.', 'The fifth major song expansion for the BeatMania series.', 'BeatMania Append 5th Mix - Time to Get Down brings the late-90s club vibe to your PS1. Master new rhythms and keep the party going.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-append-club-mix', 'Playstation', 'Beatmania Append Club Mix', '1998', 'Music', 'Konami', '2', 'Rhythm game', 'Specialized expansion focusing on underground club and house music.', 'Master the art of club-style scratching and beat-matching.', 'A genre-specific expansion for fans of deep house and club beats.', 'Beatmania Append Club Mix focuses on the authentic underground sound. Experience a more technical and rhythmic challenge in this specialized expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beatmania-append-gotta-mix-japan', 'Playstation', 'BeatMania Append Gotta Mix (Japan)', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Special expansion featuring original songs and unique remixes.', 'Achieve high scores on a variety of exclusive "Gotta Mix" tracks.', 'A creative expansion with a focus on original compositions.', 'BeatMania Append Gotta Mix offers a fresh take on the rhythm formula. Explore unique tracks found nowhere else in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head---virtual-aho-shoukougun-japan', 'Playstation', 'Beavis and Butt-Head - Virtual Aho Shoukougun (Japan)', '1999', 'Action', 'Vicom', '1', 'Adventure action', 'Point-and-click adventure game based on the MTV animated series.', 'Help the duo navigate school and town to avoid being "aho."', 'A quirky adventure game featuring the duo''s signature humor.', 'Beavis and Butt-Head - Virtual Aho Shoukougun brings the iconic pair to Japan. Experience their crude humor and bizarre situations in this unique adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-in-virtual-stupidity-english-v10', 'Playstation', 'Beavis and Butt-Head in Virtual Stupidity (English v1.0)', '1998', 'Action', 'Viacom', '1', 'Action adventure', 'Point-and-click adventure game based on the MTV animated series.', 'Navigate through Highland to help Beavis and Butt-Head find cool stuff.', 'A hilarious and faithful adaptation of the classic 90s cartoon.', 'Beavis and Butt-Head in Virtual Stupidity captures the show''s spirit perfectly. Solve puzzles and interact with the town''s weirdos in this 90s relic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade:-let-it-rip!', 'Playstation', 'Beyblade: Let it Rip!', '2002', 'Action', 'Hudson Soft', '2', 'Arena fighting', 'Competitive spinning-top battle game with customization.', 'Knock your opponent''s Beyblade out of the arena to win.', 'A faithful adaptation of the popular toy and anime franchise.', 'Beyblade: Let it Rip! lets you build and battle your own tops. Master the "Let it Rip" launch and use special attacks to dominate the stadium.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyond-the-beyond', 'Playstation', 'Beyond the Beyond', '1995', 'RPG', 'Camelot Software Planning', '1', 'Turn-based RPG', 'Traditional turn-based JRPG with a focus on exploration.', 'Lead a group of heroes to stop the revival of a dark god.', 'One of the very first JRPGs released for the PlayStation.', 'Beyond the Beyond offers a classic RPG experience. Explore a vast world, engage in turn-based combat, and experience a story of legendary proportions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-air', 'Playstation', 'Big Air', '1999', 'Sports', 'Picturehouse Interactive', '2', 'Extreme sports', '3D snowboarding game featuring tricks and racing.', 'Win various snowboarding competitions by scoring points and speed.', 'A fast-paced winter sports game with arcade-style physics.', 'Big Air brings the mountain to your screen. Perform massive tricks and navigate challenging slopes in this energetic snowboarding title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-bass-fishing', 'Playstation', 'Big Bass Fishing', '2000', 'Sports', 'Starfish', '1', 'Fishing simulation', 'Relaxing fishing simulation with a focus on large bass.', 'Catch the biggest fish across various lakes to earn trophies.', 'A straightforward and accessible fishing game for all ages.', 'Big Bass Fishing offers a tranquil yet competitive angling experience. Find the best spots and use the right lures to land a record-breaking catch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-league-slugger-baseball', 'Playstation', 'Big League Slugger Baseball', '1998', 'Sports', 'SquareSoft', '2', 'Baseball simulation', 'Arcade-style baseball simulation with exaggerated action.', 'Lead your team to victory through home runs and strikeouts.', 'A fun and accessible take on the sport of baseball.', 'Big League Slugger Baseball focuses on the fun of the game. With easy-to-learn controls and fast-paced matches, it''s a home run for sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-ol-bass-2', 'Playstation', 'Big Ol'' Bass 2', '2001', 'Sports', 'Starfish', '1', 'Fishing simulation', 'Technical fishing simulation with updated physics and locations.', 'Compete in advanced tournaments to catch the legendary "Big Ol'' Bass."', 'The sequel to the popular fishing sim with improved mechanics.', 'Big Ol'' Bass 2 offers more depth and realism for fishing enthusiasts. Explore new waters and test your skill against the smartest fish in the lake.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-strike-bowling', 'Playstation', 'Big Strike Bowling', '2000', 'Sports', 'Adrenalin Interactive', '4', 'Bowling simulation', '3D bowling simulation with various characters and lanes.', 'Bowl a perfect 300 game or win tournaments against the AI.', 'A solid and realistic bowling game for the PlayStation.', 'Big Strike Bowling brings the local lanes to your living room. Experience accurate pin physics and smooth controls in this sports favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('billiards', 'Playstation', 'Billiards', '1996', 'Sports', 'ASCII Entertainment', '2', 'Billiards simulation', '3D billiards simulation featuring various pool games.', 'Clear the table in 8-ball, 9-ball, or trick shot modes.', 'A clean and professional digital version of the classic game.', 'Billiards offers a polished pool experience. Master your angles and power to beat the competition in this realistic tabletop sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bio-freaks', 'Playstation', 'Bio F.R.E.A.K.S.', '1998', 'Fighting', 'SCE Santa Monica Studio', '2', '3D fighting', '3D flying fighting game with projectile weapons and fatalities.', 'Defeat genetically engineered mutants to survive the tournament.', 'A brutal, high-intensity 3D fighter with airborne combat mechanics.', 'Bio F.R.E.A.K.S. offers a unique twist on the fighting genre with 360-degree movement. Master cybernetic enhancements and devastating finishers in this gritty fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishi-bashi-special', 'Playstation', 'Bishi Bashi Special', '1998', 'Party', 'Konami', '4', 'Party minigames', 'Collection of fast-paced, surreal mini-games using simple controls.', 'Complete a variety of wacky challenges to earn high scores.', 'A colorful and chaotic party game that tests your reflexes.', 'Bishi Bashi Special is the ultimate party experience on PS1. Featuring dozens of bizarre and addictive mini-games, it’s a high-energy challenge for friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishi-bashi-special-japan', 'Playstation', 'Bishi Bashi Special (Japan)', '1998', 'Party', 'Konami', '4', 'Party minigames', 'Collection of fast-paced, surreal mini-games using simple controls.', 'Complete a variety of wacky challenges to earn high scores.', 'The original Japanese arcade sensation brought to the console.', 'Bishi Bashi Special (Japan) delivers the pure, frantic energy of Japanese arcade culture. Test your speed and coordination across various creative challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishi-bashi-special-2-japan', 'Playstation', 'Bishi Bashi Special 2 (Japan)', '1999', 'Party', 'Konami', '4', 'Party minigames', 'Enhanced collection of rhythmic and timing-based mini-games.', 'Master new sets of absurd and competitive arcade challenges.', 'The high-octane sequel to the most famous Japanese party game.', 'Bishi Bashi Special 2 (Japan) ramps up the difficulty and the weirdness. Experience new levels of arcade madness with refined controls and vibrant visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishi-bashi-special-3-japan', 'Playstation', 'Bishi Bashi Special 3 (Japan)', '2000', 'Party', 'Konami', '4', 'Party minigames', 'Further expansion of the Bishi Bashi mini-game formula.', 'Outperform opponents in even more complex and faster games.', 'The third installment of the legendary arcade party series.', 'Bishi Bashi Special 3 (Japan) offers the most polished version of the franchise. Perfect your timing and compete for the top spot in this chaotic collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailor-moon-supers---shin-shuyaku-soudatsusen-japan', 'Playstation', 'Bishoujo Senshi Sailor Moon SuperS - Shin Shuyaku Soudatsusen (Japan)', '1996', 'Fighting', 'Angel', '2', '2D fighting', '2D fighting game featuring characters from the Sailor Moon anime.', 'Defeat rivals in magical combat to prove your power.', 'A beautiful 2D fighter based on the SuperS season of the anime.', 'Sailor Moon SuperS - Shin Shuyaku Soudatsusen lets fans play as their favorite scouts. Master magical special moves and combos in this faithful anime fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-dawn', 'Playstation', 'Black Dawn', '1996', 'Action', 'Black Ops Entertainment', '1', 'Third-person shooter', 'First-person combat flight simulation with helicopter gameplay.', 'Pilot an AH-64 Apache to complete dangerous military operations.', 'An intense, mission-based helicopter combat simulation.', 'Black Dawn features explosive aerial action. Navigate through hostile territory and use a wide arsenal to neutralize global threats in this classic flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blade', 'Playstation', 'Blade', '2000', 'Action', 'Mucky Foot Productions', '1', 'Third-person action', 'Third-person hack-and-slash action based on the Marvel movie.', 'Hunt down vampires and eliminate Deacon Frost’s forces.', 'A dark and atmospheric action game starring the daywalker.', 'Blade for PS1 captures the cinematic intensity of the vampire hunter. Use swords and firearms to slice through the undead in this gritty action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blast-chamber', 'Playstation', 'Blast Chamber', '1996', 'Action', 'Attention to Detail', '2', '3D arena action', 'High-stakes puzzle-action game with a focus on survival.', 'Keep the explosive orb away from you until the timer runs out.', 'A unique and frantic game where you play inside a giant cube.', 'Blast Chamber is a test of nerves and speed. Navigate spinning platforms and manage the countdown to avoid a catastrophic explosion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blast-radius', 'Playstation', 'Blast Radius', '1999', 'Shooter', 'Probe Entertainment', '2', 'First-person shooter', 'Fast-paced 3D space combat and flight simulation.', 'Defeat enemy fleets and protect your sectors from invasion.', 'An arcade-style space shooter with a focus on high-speed dogfights.', 'Blast Radius delivers intense galactic warfare. Pilot advanced starfighters through asteroid fields and massive fleet battles to save humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blazing-dragons', 'Playstation', 'Blazing Dragons', '1996', 'Adventure', 'Illusions Gaming Company', '1', 'Point-and-click adventure', '2D point-and-click adventure with a focus on humor and puzzles.', 'Help Flicker the dragon become a knight and win the tournament.', 'A comedic adventure featuring the voice of Monty Python''s Terry Jones.', 'Blazing Dragons is a charming and witty take on medieval fantasy. Solve clever puzzles and enjoy a hilarious script in this cult classic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('block-kuzushi-2', 'Playstation', 'Block Kuzushi 2', '1996', 'Puzzle', 'Taito', '1', 'Block-breaking puzzle', 'Modernized brick-breaking puzzle game with various challenges.', 'Clear all the blocks in each level to progress through the map.', 'A polished sequel to the classic "breakout" style puzzle game.', 'Block Kuzushi 2 revitalizes the classic arcade formula. With new power-ups and creative level designs, it’s a perfect challenge for puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('block-kuzushi:-kowashite-help!', 'Playstation', 'Block Kuzushi: Kowashite Help!', '1997', 'Puzzle', 'Taito', '1', 'Block-breaking puzzle', 'Brick-breaking action with a character-driven rescue theme.', 'Break through obstacles to rescue characters in need.', 'A cute and engaging twist on the standard brick-breaking genre.', 'Block Kuzushi: Kowashite Help! adds a layer of personality to the arcade staple. Clear screens and save the day in this colorful puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bloody-roar', 'Playstation', 'Bloody Roar', '1997', 'Fighting', 'Eighting', '2', '3D fighting', '3D fighting game featuring characters that transform into animals.', 'Defeat opponents using human moves and powerful beast forms.', 'A revolutionary fighter known for its "Beast" transformation system.', 'Bloody Roar changes the game with its transformation mechanic. Gain new powers and health by turning into a beast mid-fight in this high-energy brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bloody-roar-2:-bringer-of-new-age', 'Playstation', 'Bloody Roar 2: Bringer of New Age', '1999', 'Fighting', 'Eighting', '2', '3D fighting', 'Refined 3D fighting with new characters and deeper combat.', 'Master the beast transformation to dominate the fighting circuit.', 'The definitive sequel to the hit transformation-based fighter.', 'Bloody Roar 2: Bringer of New Age features smoother graphics and faster combat. Discover new beast forms and master complex combos in this PS1 staple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blues-clues---blues-big-musical-usa', 'Playstation', 'Blue''s Clues - Blue''s Big Musical (USA)', '2000', 'Educational', 'Recess Software', '1', 'Musical educational', 'Educational adventure game featuring Blue and her friends.', 'Solve clues to help Blue prepare for a big musical performance.', 'A family-friendly title based on the hit Nick Jr. preschool show.', 'Blue''s Clues - Blue''s Big Musical is an interactive learning journey. Help children build logic and problem-solving skills alongside their favorite characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('board-game---top-shop', 'Playstation', 'Board Game - Top Shop', '1999', 'Board game', 'Victory Games', '4', 'Board game', 'Board game simulation with economic and building elements.', 'Manage a shopping mall and become the wealthiest shop owner.', 'A unique blend of "Monopoly" style strategy and mall management.', 'Board Game - Top Shop challenges your business savvy. Compete against friends or AI to build the ultimate retail empire in this quirky board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bob-the-builder---can-we-fix-it', 'Playstation', 'Bob the Builder - Can We Fix It', '2001', 'Adventure', 'Atomic Planet Entertainment', '1', 'Children''s adventure', 'Interactive adventure and mini-game collection for kids.', 'Help Bob and his team complete various construction projects.', 'A gentle and educational game based on the popular children''s show.', 'Bob the Builder - Can We Fix It? brings the construction site to life. Young players can participate in building tasks and problem-solving with Bob.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bogey-dead-6', 'Playstation', 'Bogey Dead 6', '1999', 'Action', 'Twilight Games', '1', 'Arcade action', '3D flight combat simulator with realistic physics.', 'Complete various military flight missions and engage in dogfights.', 'An early 3D flight sim focused on aerial dogfighting missions.', 'Bogey Dead 6 offers a classic arcade flight experience. Take to the skies in modern jets and outmaneuver the enemy in intense mission-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-fantasy-race', 'Playstation', 'Bomberman Fantasy Race', '2000', 'Racing', 'Hudson Soft', '2', 'Arcade racing', '3D racing game featuring characters from the Bomberman series.', 'Ride various creatures and use bombs to win high-speed races.', 'A fun, fantasy-themed racer with Bomberman''s signature weapons.', 'Bomberman Fantasy Race takes the classic explosive action to the track. Master different mounts and use strategic bomb placement to finish first.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-party-edition', 'Playstation', 'Bomberman Party Edition', '2000', 'Party', 'Hudson Soft', '4', 'Party minigames', 'Classic grid-based action with extensive multiplayer modes.', 'Eliminate opponents by trapping them with strategically placed bombs.', 'A massive compilation of classic Bomberman levels and modes.', 'Bomberman Party Edition is the ultimate version of the classic formula. Perfect for local multiplayer, it features a huge variety of maps and power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-wars', 'Playstation', 'Bomberman Wars', '1998', 'Strategy', 'Hudson Soft', '1', 'Tactical strategy', 'Turn-based tactical strategy game with Bomberman characters.', 'Command your units to conquer territories and defeat the enemy.', 'A strategic departure for the series, focusing on grid-based tactics.', 'Bomberman Wars adds depth to the franchise. Manage a team of bombers and use tactical positioning to win a large-scale war in this unique spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-world-usa', 'Playstation', 'Bomberman World (USA)', '1998', 'Action', 'Hudson Soft', '2', 'Arcade action', 'Classic top-down action with a story-driven campaign.', 'Traverse different elemental worlds to stop a global threat.', 'A standard Bomberman adventure featuring 3D-rendered visuals.', 'Bomberman World brings the classic gameplay into a new dimension. Explore diverse worlds and defeat giant bosses in this mission-based explosive hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowling', 'Playstation', 'Bowling', '1999', 'Sports', 'A1 Games', '4', 'Bowling simulation', 'Realistic 3D bowling simulation with multiple modes.', 'Score a perfect game or win tournaments against the computer.', 'A straightforward and fun bowling title for the PlayStation.', 'Bowling for PS1 offers smooth mechanics and accurate physics. Choose your ball and master the lanes in this accessible sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boxing', 'Playstation', 'Boxing', '1996', 'Sports', 'Acclaim Studios London', '2', 'Boxing simulation', 'Arcade-style 3D boxing game with multiple fighters.', 'Win the championship belt by knocking out all contenders.', 'A fast-paced boxing title focused on timing and power hits.', 'Boxing delivers quick, hard-hitting action. Choose your fighter and climb the ranks to become the world champion in this arcade sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brave-fencer-musashi-usa', 'Playstation', 'Brave Fencer Musashi (USA)', '1998', 'Action RPG', 'SquareSoft', '1', 'Action RPG', 'Real-time action-RPG with a focus on weapon-stealing mechanics.', 'Save the kingdom by using the magical sword Lumina to copy abilities.', 'A legendary Square title known for its humor and vibrant world.', 'Brave Fencer Musashi is a masterpiece of action and exploration. Steal enemy abilities and navigate a living world in this colorful and witty RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bravo-air-race', 'Playstation', 'Bravo Air Race', '1997', 'Racing', 'Blue Shift', '1', 'Arcade air racing', 'Aerial racing through obstacle-filled flight courses.', 'Race through the skies and finish first in global championships.', 'A unique racing game where the vehicles are historical airplanes.', 'Bravo Air Race challenges your flying skills. Master tight turns and maintain top speeds in a variety of classic aircraft across exotic tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('break-thru!-japan', 'Playstation', 'Break Thru! (Japan)', '1997', 'Action', 'Taito', '1', 'Arcade action', 'Competitive block-matching puzzle game with a versus mode.', 'Match three or more blocks of the same color to clear them.', 'A classic Japanese "match-3" style puzzle game.', 'Break Thru! is an addictive test of speed and planning. Clear your board faster than your opponent to win in this high-intensity puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breakout', 'Playstation', 'Breakout', '1996', 'Puzzle', 'SCE San Diego Studio', '2', 'Block-breaking arcade', 'Modernized 3D update of the classic paddle-and-ball game.', 'Clear all the bricks in each level while managing power-ups.', 'A visual upgrade to one of gaming''s most iconic arcade formulas.', 'Breakout for PS1 brings the brick-breaking genre into the 3D era. Face challenging levels and massive bosses in this vibrant arcade update.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breakout-usa', 'Playstation', 'Breakout (USA)', '1996', 'Puzzle', 'SCE San Diego Studio', '2', 'Block-breaking arcade', 'Modernized 3D update of the classic paddle-and-ball game.', 'Clear all the bricks in each level while managing power-ups.', 'A visual upgrade to one of gaming''s most iconic arcade formulas.', 'Breakout for PS1 brings the brick-breaking genre into the 3D era. Face challenging levels and massive bosses in this vibrant arcade update.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-iii', 'Playstation', 'Breath of Fire III', '1997', 'RPG', 'Capcom', '1', 'Turn-based RPG', 'Turn-based JRPG with isometric graphics and a deep dragon system.', 'Journey with Ryu to uncover the secrets of the brood''s past.', 'A critically acclaimed RPG with a beautiful hand-drawn art style.', 'Breath of Fire III is a classic of the genre. Features a deep "Master" system, complex dragon transformations, and an emotional, expansive story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('breath-of-fire-iv-usa', 'Playstation', 'Breath of Fire IV (USA)', '2000', 'RPG', 'Capcom', '1', 'Turn-based RPG', 'Turn-based JRPG featuring a unique cel-shaded visual style.', 'Explore a desert-filled world to find the missing princess.', 'A visual masterpiece with one of the best combat systems on PS1.', 'Breath of Fire IV offers a dual-perspective narrative. Experience a rich world of magic and spirits with incredible animation and strategic combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brigandine---grand-edition---cross-mod-v61b', 'Playstation', 'Brigandine - Grand Edition - Cross MOD (v.6.1b)', '2000', 'Strategy', 'Hearty Robin', '1', 'Tactical RPG', 'Turn-based tactical strategy game with an expanded story and units.', 'Conquer the continent of Forsena and unite the six nations.', 'The ultimate version of the cult-classic fantasy strategy game.', 'Brigandine - Grand Edition adds multiplayer and new cinematic events. Manage your generals and monsters to dominate the map in this deep tactical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brigandine---grand-edition-japan-t-en-by-john-osborne-v8-english-voices-v2', 'Playstation', 'Brigandine - Grand Edition (Japan) [T-En by John Osborne v8] [English Voices v2]', '1998', 'Strategy', 'Hearty Robin', '1', 'Tactical RPG', 'Turn-based tactical strategy game with an expanded story and units.', 'Conquer the continent of Forsena and unite the six nations.', 'The ultimate version of the cult-classic fantasy strategy game.', 'Brigandine - Grand Edition adds multiplayer and new cinematic events. Manage your generals and monsters to dominate the map in this deep tactical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brigandine---the-legend-of-forsena-usa', 'Playstation', 'Brigandine - The Legend of Forsena (USA)', '1998', 'Strategy', 'Hearty Robin', '1', 'Tactical RPG', 'Turn-based tactical strategy featuring large-scale army battles.', 'Choose one of six nations and conquer the entire continent.', 'A deep and rewarding mix of strategy, management, and RPG.', 'Brigandine - The Legend of Forsena is a tactical masterpiece. Command Rune Knights and armies of monsters to seize territory in this epic fantasy war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brightis', 'Playstation', 'Brightis', '1999', 'Puzzle', 'Taito', '1', 'Block-breaking puzzle', 'Real-time action RPG with 3D environments and overhead perspective.', 'Explore dungeons and defeat monsters to uncover an ancient mystery.', 'A visually impressive late-era PS1 action RPG from Japan.', 'Brightis offers a deep action-adventure experience with a unique 3D engine. Master real-time combat and explore a rich fantasy world in this hidden PlayStation gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-helix-usa', 'Playstation', 'Broken Helix (USA)', '1998', 'Action', 'Criterion Games', '1', 'Third-person shooter', 'Third-person shooter with hybrid exploration and puzzle elements.', 'Infiltrate a base and stop a biochemical threat before time runs out.', 'A sci-fi action game featuring voice acting by Bruce Campbell.', 'Broken Helix provides a non-linear mission structure with multiple paths. Experience intense shooting and 4-way character perspectives in this high-stakes sci-fi thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('broken-sword-ii---the-smoking-mirror-usa', 'Playstation', 'Broken Sword II - The Smoking Mirror (USA)', '1997', 'Adventure', 'Revolution Software', '1', 'Point-and-click adventure', 'Point-and-click adventure with hand-drawn animation and logic puzzles.', 'Investigate a mysterious Mayan conspiracy to save the world.', 'The acclaimed sequel to the classic "Circle of Blood" adventure.', 'Broken Sword II - The Smoking Mirror features a deep, cinematic narrative. Solve complex puzzles and explore global locations in this masterpiece of the adventure genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-also-featuring-rainbow-islands', 'Playstation', 'Bubble Bobble Also Featuring Rainbow Islands', '1996', 'Platformer', 'Taito', '2', 'Arcade platformer', 'Single-screen arcade platformer with bubble-shooting mechanics.', 'Clear all enemies on each screen to advance through the towers.', 'A compilation of the legendary arcade hits Bubble Bobble and Rainbow Islands.', 'Experience two arcade classics in one package. Bubble Bobble Also Featuring Rainbow Islands delivers addictive, colorful platforming action perfect for high-score chasers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubsy-3d---furbitten-planet', 'Playstation', 'Bubsy 3D - Furbitten Planet', '1996', 'Platformer', 'Eidetic', '1', '3D platformer', '3D platformer with tank controls and large vertical levels.', 'Collect atoms and defeat the alien invaders to save the planet.', 'A quirky, fully 3D platformer starring the wisecracking Bubsy.', 'Bubsy 3D - Furbitten Planet is a unique piece of gaming history. Navigate surreal 3D environments and use your glide ability to overcome challenging platforming stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buckle-up!', 'Playstation', 'Buckle Up!', '1998', 'Racing', 'Titus Interactive', '2', 'Arcade racing', 'Arcade-style racing with a focus on demolition and speed.', 'Finish the race in first place while wrecking your opponents.', 'A fast-paced budget racer with simple mechanics and high-speed thrills.', 'Buckle Up! delivers straightforward arcade driving action. Choose your car and master the tracks while avoiding total destruction in this competitive racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny-&-taz:-time-busters', 'Playstation', 'Bugs Bunny & Taz: Time Busters', '2000', 'Platformer', 'Behaviour Interactive', '2', '3D platformer', 'Cooperative 3D platformer featuring character switching and gadgets.', 'Travel through time to rescue Daffy Duck and restore the timeline.', 'A charming and funny adventure starring the iconic Looney Tunes duo.', 'Bugs Bunny & Taz: Time Busters is a perfect co-op experience. Use Bugs'' gadgets and Taz''s strength to solve puzzles and defeat bosses across history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny:-lost-in-time', 'Playstation', 'Bugs Bunny: Lost in Time', '1999', 'Platformer', 'Behaviour Interactive', '1', '3D platformer', '3D platformer with exploration, puzzles, and hidden collectibles.', 'Find all the clock pieces to return to the present time.', 'A nostalgic and faithful 3D adaptation of the Looney Tunes universe.', 'Bugs Bunny: Lost in Time captures the humor and style of the cartoons. Explore different eras, from the Stone Age to the Future, in this classic platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burning-road', 'Playstation', 'Burning Road', '1996', 'Racing', 'Titus Interactive', '2', 'Arcade racing', 'High-speed arcade racing with drift-heavy handling and loud music.', 'Win the championship by defeating rivals on diverse tracks.', 'A fast and flashy racer heavily inspired by Sega''s Daytona USA.', 'Burning Road brings the arcade feel to the PS1. Master the drift mechanics and push your car to the limit in this vibrant, high-energy racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('burstrick:-wake-boarding!!', 'Playstation', 'BursTrick: Wake Boarding!!', '2000', 'Sports', 'Taito', '2', 'Wakeboarding sports', 'Wakeboarding simulation with tricks and water physics.', 'Perform high-scoring stunts and complete courses across various lakes.', 'A niche water sports game focusing on timing and board control.', 'BursTrick: Wake Boarding!! offers a unique take on the extreme sports genre. Pull off massive air tricks and master the wake in this specialized simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bushido-blade', 'Playstation', 'Bushido Blade', '1997', 'Fighting', 'Square', '2', 'Weapon-based fighting', 'Realistic 3D sword fighting without health bars; one hit can kill.', 'Defeat your opponent in a duel using timing and precision.', 'A revolutionary, cinematic fighting game focused on realism.', 'Bushido Blade redefines the fighting genre. With no time limits or health bars, every move counts in this tense, strategic duel to the death.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bushido-blade-2', 'Playstation', 'Bushido Blade 2', '1998', 'Fighting', 'Square', '2', 'Weapon-based fighting', 'Refined 3D sword combat with new characters and faster movement.', 'Defeat the rival clan and master your chosen weapon''s style.', 'The intense sequel to the original "one-hit-kill" fighting game.', 'Bushido Blade 2 enhances the tactical combat of the original. Featuring more weapons and characters, it provides the ultimate high-stakes samurai experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-4', 'Playstation', 'Bust-A-Move 4', '1998', 'Puzzle', 'Taito', '2', 'Arcade puzzle', 'Bubble-shooting puzzle game with new characters and trick shots.', 'Clear the board by matching colored bubbles to defeat opponents.', 'The fourth entry in the beloved and addictive puzzle series.', 'Bust-A-Move 4 introduces a new chain reaction system and pulley puzzles. Compete against the AI or friends in the most feature-rich entry of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buster-bros-collection', 'Playstation', 'Buster Bros Collection', '1998', 'Shooter', 'Capcom', '2', 'Arcade shooter', 'Static-screen puzzle game focusing on popping bouncing balls.', 'Destroy all the bubbles on screen using harpoons and power-ups.', 'A collection of the classic Pang / Buster Bros arcade hits.', 'Buster Bros Collection brings the timeless arcade fun of Pang to the PS1. Test your reflexes and strategy across hundreds of challenging, ball-popping levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buzz-lightyear-of-star-command', 'Playstation', 'Buzz Lightyear of Star Command', '2000', 'Action', 'Traveller''s Tales', '1', 'Action adventure', 'Third-person action-adventure with shooting and exploration.', 'Stop Zurg''s evil plan across different planetary locations.', 'An action-packed game based on the Toy Story spin-off cartoon.', 'Buzz Lightyear of Star Command lets you play as the galaxy''s top Space Ranger. Use an array of futuristic weapons and gadgets to protect the universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('c-12-final-resistance', 'Playstation', 'C-12 Final Resistance', '1998', 'Shooter', 'SCE Cambridge Studio', '1', 'Third-person shooter', 'Sci-fi third-person shooter with a focus on tactical combat.', 'Fight through an alien-invaded Earth to stop the cyborg menace.', 'A late-generation PS1 action game with impressive 3D visuals.', 'C-12 Final Resistance delivers intense combat and mission-based gameplay. Help the human resistance reclaim the planet from mechanical invaders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('c:-the-contra-adventure', 'Playstation', 'C: The Contra Adventure', '1998', 'Action', 'Appaloosa Interactive', '2', 'Side-scrolling action', 'Side-scrolling run-and-gun action with 3D elements.', 'Fight through alien-infested levels to stop the planetary threat.', 'A unique 3D-styled entry in the legendary Contra series.', 'C: The Contra Adventure returns to the series'' roots while adding new perspectives. Face massive bosses and intense fire-fights in this hardcore shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('c3-racing', 'Playstation', 'C3 Racing', '1998', 'Racing', 'Eutechnyx', '2', 'Arcade racing', 'High-performance circuit racing with various car classes.', 'Win the global tour to unlock faster cars and more tracks.', 'A sleek arcade racer focused on clean lines and speed.', 'C3 Racing offers a polished driving experience with a great sense of speed. Compete on global circuits to prove you are the fastest driver on the grid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cabelas-big-game-hunter---ultimate-challenge', 'Playstation', 'Cabela''s Big Game Hunter - Ultimate Challenge', '2001', 'Sports', 'Sand Grain Studios', '1', 'Hunting simulation', 'First-person hunting simulation with a focus on realism.', 'Track and hunt various big game animals in authentic habitats.', 'A detailed hunting game emphasizing stealth and weapon choice.', 'Cabela''s Big Game Hunter - Ultimate Challenge brings the outdoor experience to PS1. Plan your approach and take the perfect shot in this realistic sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caesars-palace-2000---millennium-gold-edition', 'Playstation', 'Caesars Palace 2000 - Millennium Gold Edition', '2000', 'Gambling', 'Runecraft', '4', 'Casino simulation', 'Casino simulation featuring various gambling games.', 'Win big at the tables and increase your digital bankroll.', 'A comprehensive casino game featuring slots, poker, and more.', 'Caesars Palace 2000 provides a realistic Las Vegas atmosphere. Try your luck at blackjack, craps, or roulette in this officially licensed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('calis-geo-tools', 'Playstation', 'Cali''s Geo Tools', '1997', 'Educational', 'Titus Interactive', '1', 'Educational puzzle', 'Educational and utility tools for geography and mapping.', 'Explore and learn about global geography through various tools.', 'A niche utility title designed for learning and information.', 'Cali''s Geo Tools offers an interactive way to study the world. Explore maps and geographical data in this unique educational PlayStation title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('capcom-vs-snk:-millennium-fight-2000', 'Playstation', 'Capcom vs. SNK: Millennium Fight 2000', '2000', 'Fighting', 'Capcom', '2', '2D fighting', '2D crossover fighting game featuring legendary rosters from both companies.', 'Defeat all rivals to determine the ultimate fighting universe.', 'A dream-match fighter with pixel-perfect 2D animation.', 'Capcom vs. SNK: Millennium Fight 2000 brings the giants of the arcade together. Master the "Ratio" system and iconic special moves in this historic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('capcom-vs-snk:-millennium-fight-2000-pro-europe', 'Playstation', 'Capcom vs. SNK: Millennium Fight 2000 Pro (Europe)', '2001', 'Fighting', 'Capcom', '2', '2D fighting', 'Refined 2D crossover fighter with extra characters and modes.', 'Win the final tournament using specialized fighting styles.', 'The enhanced "Pro" version of the legendary crossover title.', 'Capcom vs. SNK Pro features balanced gameplay and additional playable characters. It is the definitive 2D fighting experience for crossover fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-commando', 'Playstation', 'Captain Commando', '1995', 'Action', 'Capcom', '2', 'Side-scrolling beat ''em up', 'Side-scrolling beat ''em up featuring a squad of unique heroes.', 'Clean up the streets and stop a global criminal organization.', 'A faithful port of Capcom''s classic futuristic arcade brawler.', 'Captain Commando offers high-energy 4-player style action. Fight through colorful levels and use unique abilities to save the city from crime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-tsubasa-j:-get-in-the-tomorrow', 'Playstation', 'Captain Tsubasa J: Get In The Tomorrow', '1997', 'Sports', 'Tecmo', '2', 'Arcade soccer', 'Strategic soccer game with special moves and anime cutscenes.', 'Lead Tsubasa and his team to win the World Youth championship.', 'A sports/RPG hybrid based on the popular football anime.', 'Captain Tsubasa J: Get In The Tomorrow features explosive special shots and cinematic action. Experience the thrill of the anime on the soccer pitch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-captor-sakura---clowcard-magic-japan', 'Playstation', 'Card Captor Sakura - Clowcard Magic (Japan)', '1999', 'Adventure', 'Arika', '1', 'Card battle adventure', 'Puzzle game based on the Card Captor Sakura anime series.', 'Capture the Clow Cards by solving various logic puzzles.', 'A colorful and charming puzzle game for fans of the franchise.', 'Card Captor Sakura - Clowcard Magic combines the show''s lore with addictive gameplay. Help Sakura capture all the cards in this beautifully presented title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('card-games', 'Playstation', 'Card Games', '1998', 'Card game', 'ASCII Entertainment', '4', 'Card game', 'Digital collection of various classic card games.', 'Win matches in Poker, Solitaire, and other card staples.', 'A straightforward and relaxing collection of tabletop games.', 'Card Games for PS1 provides a portable casino and card room experience. Perfect for quick sessions and casual fans of traditional games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cardinal-syn-usa', 'Playstation', 'Cardinal Syn (USA)', '1999', 'Action', 'Krome Studios', '2', 'Third-person action', 'Dark 3D weapon-based fighting game with a fantasy setting.', 'Defeat all rivals to claim the Book of Knowledge.', 'A gritty 3D fighter featuring unique characters and magic.', 'Cardinal Syn offers brutal weapon combat in a dark fantasy world. Master environmental hazards and complex combos to survive the tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carmageddon', 'Playstation', 'Carmageddon', '1997', 'Racing', 'Torus Games', '2', 'Vehicular combat racing', 'Vehicular combat and racing where hitting pedestrians earns points.', 'Win the race or destroy all opponents in a chaotic derby.', 'A controversial and high-energy combat racing classic.', 'Carmageddon is the ultimate game of vehicular carnage. Race through urban environments where the rules of the road don''t exist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carnage-heart', 'Playstation', 'Carnage Heart', '1997', 'Strategy', 'Artdink', '1', 'Real-time strategy', 'Turn-based tactical strategy involving giant customizable robots.', 'Design and program your mechs to win battles automatically.', 'A unique and deep strategy game focused on programming.', 'Carnage Heart is a thinker''s game. Build your mechs and code their AI to outsmart the enemy on the battlefield in this deep tactical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casper', 'Playstation', 'Casper', '1996', 'Adventure', 'Interplay', '1', 'Action adventure', '3D action-adventure featuring puzzles and exploration.', 'Help Casper find his friends and stop Kibosh''s evil plan.', 'A family-friendly adventure based on the friendly ghost movie.', 'Casper for PS1 allows you to explore Whipstaff Manor. Use Casper''s ghostly abilities to solve puzzles and interact with the living in this charming title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casper---friends-around-the-world', 'Playstation', 'Casper - Friends Around the World', '1997', 'Adventure', 'Behaviour Interactive', '1', 'Children''s adventure', '3D platformer featuring Casper traveling across the globe.', 'Rescue Casper''s friends who have been captured by Kibosh.', 'An expansive sequel taking the ghostly action worldwide.', 'Casper - Friends Around the World offers varied levels and fun platforming. Visit different countries and use new powers to save your ghostly pals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---rondo-of-the-night', 'Playstation', 'Castlevania - Rondo of the Night', '1993', 'Action platformer', 'Konami', '1', 'Classic action platformer', '2D side-scrolling action-platformer with a classic vampire theme.', 'Guide Richter Belmont to defeat Dracula in his dark castle.', 'The legendary PC Engine classic, also known as Nocturne in the Moonlight.', 'Castlevania - Rondo of the Night (SotN) is a masterpiece of design. Experience the pinnacle of 2D action with branching paths and incredible music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---symphony-of-the-night', 'Playstation', 'Castlevania - Symphony Of The Night', '1997', 'Action platformer', 'Konami', '1', 'Metroidvania', '2D action-RPG with exploration and a massive "Metroidvania" map.', 'Explore Dracula''s castle as Alucard to stop the dark lord''s return.', 'Widely considered one of the greatest video games of all time.', 'Castlevania - Symphony Of The Night redefined the series. Explore a vast, non-linear castle, level up your character, and uncover multiple endings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---symphony-of-the-night---quality-hack', 'Playstation', 'Castlevania - Symphony of the Night - Quality hack', '1997', 'Action platformer', 'Konami', '1', 'Metroidvania', 'Enhanced version of the 2D action-RPG with bug fixes and improvements.', 'Explore Dracula''s castle and achieve the true ending.', 'A fan-improved version of the legendary "SotN" experience.', 'Castlevania - Symphony of the Night - Quality hack provides the definitive way to play. Enjoy smoother performance and corrected translations in this RPG masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-chronicles', 'Playstation', 'Castlevania Chronicles', '2001', 'Action platformer', 'Konami', '1', 'Classic action platformer', 'Side-scrolling 2D action-platformer with a classic whip-based combat.', 'Guide Simon Belmont through Dracula''s castle to defeat the dark lord.', 'A refined remake of the original X68000 Castlevania classic.', 'Castlevania Chronicles brings the legendary vampire-hunting action to PS1. Experience enhanced graphics, a haunting soundtrack, and brutal difficulty in this definitive arcade-style adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castrol-honda-superbike-racing', 'Playstation', 'Castrol Honda Superbike Racing', '1997', 'Racing', 'Interactive Entertainment', '2', 'Motorcycle racing simulation', 'Realistic motorcycle racing simulation with licensed Honda bikes.', 'Win the Superbike World Championship by mastering various tracks.', 'A technical and authentic motorcycle racing experience.', 'Castrol Honda Superbike Racing delivers high-speed thrills with realistic physics. Tune your bike and compete against the best riders in this licensed racing simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cat-in-the-hat-the', 'Playstation', 'Cat in the Hat, The', '2000', 'Platformer', 'Mindscape', '1', '3D platformer', '2D side-scrolling platformer based on the classic Dr. Seuss book.', 'Navigate through surreal levels to help the children clean up the mess.', 'A colorful and whimsical platformer for younger audiences.', 'The Cat in the Hat brings the magic of Dr. Seuss to life. Explore vibrant worlds and solve simple puzzles in this charming family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('centipede', 'Playstation', 'Centipede', '1998', 'Shooter', 'Leaping Lizard Software', '2', 'Arcade shooter', 'Modernized 3D shooter based on the classic arcade game.', 'Protect the garden by shooting waves of centipedes and insects.', 'A fast-paced reimagining of the foundational arcade hit.', 'Centipede on PS1 offers a 32-bit twist on the classic formula. Face giant bosses and swarms of enemies in this high-intensity arcade shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chaos-break', 'Playstation', 'Chaos Break', '2000', 'Action', 'Eidos Interactive', '2', '3D action adventure', 'Third-person survival horror with action and puzzle-solving elements.', 'Investigate a bio-hazard facility and survive the thermal outbreak.', 'A cinematic horror game often compared to Resident Evil.', 'Chaos Break delivers tense atmosphere and intense combat. Uncover the mystery behind the creature outbreak in this technical survival horror thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chess', 'Playstation', 'Chess', '1996', 'Board game', 'Krisalis Software', '2', 'Chess simulation', 'Traditional board game simulation with multiple difficulty levels.', 'Checkmate the opponent''s king using strategic moves.', 'A clean and straightforward digital version of the game of kings.', 'Chess for PS1 provides a solid platform for players of all levels. Improve your strategy with AI opponents and classic board game mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-3-d-the', 'Playstation', 'Chessmaster 3-D, The', '1995', 'Board game', 'The Software Toolworks', '2', '3D chess simulation', 'Advanced 3D chess simulation with tutorials and diverse AI.', 'Learn the game of chess and defeat the Master''s AI challenges.', 'A feature-rich chess sim known for its depth and teaching tools.', 'The Chessmaster 3-D is the ultimate digital chess board. Master the game with detailed tutorials and a wide variety of 3D board designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-ii', 'Playstation', 'Chessmaster II', '1993', 'Board game', 'The Software Toolworks', '2', 'Chess simulation', 'Refined chess simulation with an improved engine and visuals.', 'Climb the ranks of chess masters by winning competitive matches.', 'The definitive chess experience on PS1 with a massive AI database.', 'Chessmaster II offers professional-grade chess gameplay. Analyze your moves and challenge one of the most advanced AI engines of the 32-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicken-run', 'Playstation', 'Chicken Run', '2000', 'Adventure', 'Blitz Games', '1', 'Action adventure', 'Stealth-based 3D platformer with puzzle-solving elements.', 'Help Ginger and the flock escape the farm to avoid being pies.', 'A clever and funny adaptation of the Aardman animation film.', 'Chicken Run features mission-based gameplay where stealth is key. Plan your escape and outsmart the farmers in this faithful movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chocobo-racing', 'Playstation', 'Chocobo Racing', '1999', 'Racing', 'Square', '2', 'Arcade kart racing', 'Kart-style racing featuring characters from the Final Fantasy series.', 'Win races and unlock new magical abilities and characters.', 'A charming and competitive racer set in the Chocobo universe.', 'Chocobo Racing brings magic to the track. Use spells and unique abilities to outpace your rivals in this colorful and addictive kart racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chou-aniki---kyuukyoku-muteki-ginga-saikyou-otoko', 'Playstation', 'Chou-Aniki - Kyuukyoku Muteki Ginga Saikyou Otoko', '1995', 'Action', 'Masaya', '1', 'Arcade action shooter', 'Bizarre side-scrolling shooter with body-building themes.', 'Defeat surreal enemies across the galaxy to prove your strength.', 'A cult-classic Japanese "shmup" known for its weirdness.', 'Chou-Aniki features over-the-top visuals and high-intensity shooting. Experience one of the most unique and strange shooters ever released on the PlayStation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chronicles-of-the-sword-usa-disc-1', 'Playstation', 'Chronicles of the Sword (USA) (Disc 1)', '2000', 'Action', 'Eidos Interactive', '1', 'Third-person action', 'Point-and-click adventure with a medieval fantasy setting.', 'Navigate puzzles and dialogue to solve a royal conspiracy.', 'A cinematic adventure spanning two discs of deep lore.', 'Chronicles of the Sword offers a traditional adventure experience. Explore the world of King Arthur and uncover dark secrets in this narrative-driven quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chronicles-of-the-sword-usa-disc-2', 'Playstation', 'Chronicles of the Sword (USA) (Disc 2)', '2000', 'Action', 'Eidos Interactive', '1', 'Third-person action', 'Point-and-click adventure with a medieval fantasy setting.', 'Navigate puzzles and dialogue to solve a royal conspiracy.', 'The concluding half of the epic Arthurian adventure.', 'Chronicles of the Sword (Disc 2) continues the high-stakes journey. Solve intricate puzzles and bring justice to the kingdom in this classic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chrono-cross-usa', 'Playstation', 'Chrono Cross (USA)', '2000', 'RPG', 'Square', '1', 'JRPG', 'Turn-based JRPG with a focus on a multi-dimensional narrative.', 'Travel between two parallel worlds to uncover the protagonist''s fate.', 'A legendary sequel to Chrono Trigger with stunning visuals.', 'Chrono Cross is a masterpiece of storytelling and music. Recruit dozens of characters and master an innovative battle system in this RPG classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('circuit-breakers', 'Playstation', 'Circuit Breakers', '1998', 'Racing', 'Traveller''s Tales', '4', 'Top-down arcade racing', 'Top-down arcade racing with small, fast vehicles and weapons.', 'Finish first in chaotic races while using power-ups to stop rivals.', 'A high-energy racer inspired by the Micro Machines formula.', 'Circuit Breakers offers addictive multiplayer action. Race through diverse environments and blast your opponents off the track in this arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('city-of-lost-children', 'Playstation', 'City of Lost Children', '1996', 'Adventure', 'Psygnosis', '1', 'Cinematic adventure', 'Atmospheric adventure game based on the surreal French film.', 'Solve complex puzzles to rescue kidnapped children from a madman.', 'A dark and visually unique point-and-click style adventure.', 'City of Lost Children captures the eerie aesthetic of the movie. Explore a dreamlike city and solve environmental puzzles in this atmospheric title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('civilization-ii', 'Playstation', 'Civilization II', '1996', 'Strategy', 'MicroProse', '1', 'Turn-based strategy', 'Turn-based strategy focusing on the evolution of human history.', 'Build an empire to stand the test of time and conquer the world.', 'The console port of the legendary world-building strategy game.', 'Civilization II provides deep tactical gameplay. Manage resources, research technologies, and engage in diplomacy in this definitive empire sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cleopatra-fortune', 'Playstation', 'Cleopatra Fortune', '1996', 'Puzzle', 'Taito', '2', 'Arcade puzzle', 'Falling-block puzzle game with an ancient Egyptian theme.', 'Capture gems by surrounding them with blocks of the same color.', 'A unique and addictive twist on the match-3 puzzle genre.', 'Cleopatra Fortune challenges your spatial logic. Clear the board and earn high scores in this vibrant and fast-paced Egyptian puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cleopatras-fortune', 'Playstation', 'Cleopatra''s Fortune', '1996', 'Puzzle', 'Taito', '2', 'Arcade puzzle', 'Falling-block puzzle game with an ancient Egyptian theme.', 'Capture gems by surrounding them with blocks of the same color.', 'A unique and addictive twist on the match-3 puzzle genre.', 'Cleopatra''s Fortune challenges your spatial logic. Clear the board and earn high scores in this vibrant and fast-paced Egyptian puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clock-tower', 'Playstation', 'Clock Tower', '1997', 'Horror', 'Human Entertainment', '1', 'Survival horror', 'Point-and-click survival horror with a focus on hiding and puzzles.', 'Survive the pursuit of the Scissorman and escape the mansion.', 'A terrifying cult classic that popularized the slasher genre in games.', 'Clock Tower delivers pure suspense. With no combat, you must use your wits to hide and survive one of the most iconic horror villains in history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clock-tower-ii:-the-struggle-within', 'Playstation', 'Clock Tower II: The Struggle Within', '1999', 'Horror', 'Human Entertainment', '1', 'Psychological horror', 'Psychological horror adventure with multiple storylines and endings.', 'Survive the Scissorman''s return and uncover a dark family secret.', 'A tense sequel featuring improved graphics and multiple characters.', 'Clock Tower II: The Struggle Within expands the horror formula. Manage a dual-personality protagonist and solve twisted puzzles to stay alive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clock-tower:-the-first-fear', 'Playstation', 'Clock Tower: The First Fear', '1995', 'Horror', 'Human Entertainment', '1', 'Survival horror', 'Enhanced 2D survival horror adventure with multiple endings.', 'Help Jennifer escape the Barrows Mansion and the Scissorman.', 'The PlayStation port of the original SNES horror masterpiece.', 'Clock Tower: The First Fear is where the nightmare began. Experience the original slasher horror with updated sound and visuals on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('codename:-tenka', 'Playstation', 'Codename: Tenka', '1996', 'Shooter', 'Psygnosis', '1', 'First-person shooter', 'First-person shooter with a focus on high-tech weaponry.', 'Infiltrate a planetary facility and destroy the evil corporation.', 'A dark, sci-fi FPS with impressive lighting and atmosphere.', 'Codename: Tenka features an innovative weapon system and gritty environments. Battle through waves of cybernetic enemies to save the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colin-mcrae-rally', 'Playstation', 'Colin McRae Rally', '1998', 'Racing', 'Codemasters', '2', 'Rally racing simulation', 'Realistic rally racing simulation with licensed cars and stages.', 'Complete time trials across global rally circuits to win the trophy.', 'The game that set the standard for realistic rally racing.', 'Colin McRae Rally offers precise handling and authentic mud-splattered action. Master the art of the drift in this legendary racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colin-mcrae-rally-20', 'Playstation', 'Colin McRae Rally 2.0', '2000', 'Racing', 'Codemasters', '2', 'Rally racing simulation', 'Refined rally racing with improved graphics and car physics.', 'Compete in a global rally championship and manage car damage.', 'The high-performance sequel to the world''s top rally sim.', 'Colin McRae Rally 2.0 delivers the ultimate off-road experience. Featuring more cars and technical tracks, it is a pinnacle of PS1 racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colony-wars', 'Playstation', 'Colony Wars', '1997', 'Shooter', 'Psygnosis', '1', 'Space combat shooter', 'Space combat simulation featuring large-scale fleet battles.', 'Fight for the League of Free Worlds in a galactic war.', 'A cinematic flight sim with a deep branching narrative.', 'Colony Wars redefined space combat on the PS1. Engage in epic dogfights and protect massive capital ships in this visually stunning epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('colony-wars-3:-red-sun', 'Playstation', 'Colony Wars 3: Red Sun', '1999', 'Shooter', 'Psygnosis', '1', 'Space combat shooter', 'Space combat action with a focus on a single mercenary''s journey.', 'Complete missions to uncover a mystery at the edge of the sun.', 'The third entry in the series, moving to a mission-based structure.', 'Colony Wars 3: Red Sun offers more freedom and new ship upgrades. Experience intense space battles in this refined and action-heavy sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-&-conquer', 'Playstation', 'Command & Conquer', '1995', 'Strategy', 'Westwood Studios', '2', 'Real-time strategy', 'Real-time strategy focusing on resource management and war.', 'Lead the GDI or Brotherhood of Nod to global dominance.', 'The foundational RTS that brought the genre to consoles.', 'Command & Conquer offers deep strategy and cinematic FMV. Build your base, train your army, and crush the enemy in this genre-defining hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('command-&-conquer-red-alert', 'Playstation', 'Command & Conquer Red Alert', '1996', 'Strategy', 'Westwood Studios', '2', 'Real-time strategy', 'Real-time strategy set in an alternate history Cold War.', 'Command Soviet or Allied forces to win the battle for Europe.', 'A massive RTS expansion with new units and iconic music.', 'Command & Conquer Red Alert brings high-stakes warfare to the PS1. Master the battlefield with tanks, spies, and Tesla coils in this strategy masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contender-2', 'Playstation', 'Contender 2', '1999', 'Sports', 'High Voltage Software', '2', 'Boxing simulation', '3D arcade-style boxing with a focus on speed and combos.', 'Win the championship by knocking out a series of diverse boxers.', 'A fast-paced and accessible boxing title for sports fans.', 'Contender 2 offers improved visuals and tighter controls than its predecessor. Rise through the ranks and become a legend in the ring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('contra-legacy-of-war', 'Playstation', 'Contra Legacy Of War', '1998', 'Action', 'Appaloosa Interactive', '2', 'Side-scrolling action', '3D side-scrolling action-platformer with explosive combat.', 'Stop a global terrorist threat using heavy weaponry and heroes.', 'A 32-bit entry in the legendary run-and-gun shooter series.', 'Contra Legacy Of War brings the classic difficulty to a new perspective. Battle giant mechanical bosses and survive waves of enemies in this intense shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmic-race', 'Playstation', 'Cosmic Race', '1999', 'Racing', 'Silicon Dreams Studio', '2', 'Futuristic racing', 'High-speed futuristic racing with 3D flight mechanics.', 'Win races through bizarre and abstract space-themed tracks.', 'A visually unique and abstract racing game from early PS1 era.', 'Cosmic Race offers a surreal driving experience. Navigate through strange dimensions and outpace your rivals in this experimental racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cowboy-bebop', 'Playstation', 'Cowboy Bebop', '1998', 'Action', 'Bandai', '1', 'Action adventure', 'Third-person action game based on the hit space-western anime.', 'Capture bounties across the solar system as Spike Spiegel.', 'A stylish action title featuring the anime''s iconic jazz soundtrack.', 'Cowboy Bebop for PS1 lets you pilot the Swordfish II in intense dogfights. Relive the aesthetic of the series in this mission-based action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot', 'Playstation', 'Crash Bandicoot', '1996', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D corridor platformer with a focus on timing and crates.', 'Stop Dr. Neo Cortex and rescue Crash''s girlfriend, Tawna.', 'The legendary PlayStation mascot''s debut adventure.', 'Crash Bandicoot is a 3D platforming icon. Navigate through vibrant jungle levels, break crates, and defeat quirky bosses in this definitive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot---warped', 'Playstation', 'Crash Bandicoot - Warped', '1998', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D platforming with varied vehicle levels and power-up abilities.', 'Travel through time to collect crystals and stop Dr. Nefarious Tropy.', 'The third and most diverse entry in the original Crash trilogy.', 'Crash Bandicoot - Warped takes the platforming to new eras. Pilot planes, ride motorcycles, and use new abilities like the fruit bazooka to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-apr-8-1996-prototype', 'Playstation', 'Crash Bandicoot (Apr 8, 1996 prototype)', '1996', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D corridor platforming in an unfinished, early development state.', 'Navigate through early jungle levels and test game mechanics.', 'An early April 1996 prototype showing the origins of the series.', 'Explore gaming history with this Crash Bandicoot 1996 prototype. Experience the raw development phase of the world''s most famous bandicoot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-japan', 'Playstation', 'Crash Bandicoot (Japan)', '1996', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D corridor platforming with localized voices and unique hints.', 'Stop Dr. Neo Cortex and save the Wumpa Islands.', 'The Japanese version of the classic platformer with regional tweaks.', 'Experience the Japanese release of Crash Bandicoot. Featuring unique Aku Aku hints and localized presentation, it''s a must-play for collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-jul-15-1996-prototype', 'Playstation', 'Crash Bandicoot (Jul 15, 1996 prototype)', '1996', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D corridor platforming in a near-final development state.', 'Reach the end of the levels and defeat the bosses.', 'A mid-July 1996 prototype featuring almost complete gameplay.', 'This July 1996 prototype of Crash Bandicoot offers a look at the final polish of the game before its legendary release on the PlayStation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-may-11-1996-prototype', 'Playstation', 'Crash Bandicoot (May 11, 1996 prototype)', '1996', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D corridor platforming in a preliminary development state.', 'Test early level layouts and character animations.', 'A rare May 1996 prototype showcasing early environment designs.', 'Discover the evolution of 3D platforming with this May 1996 Crash Bandicoot build. See how the iconic levels were structured before the final launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-2---cortex-no-gyakushuu!-japan', 'Playstation', 'Crash Bandicoot 2 - Cortex no Gyakushuu! (Japan)', '1997', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D platforming featuring the warp room and crystal collection.', 'Collect 25 crystals to help Dr. Cortex (or so he says).', 'The Japanese edition of the critically acclaimed sequel.', 'Crash Bandicoot 2 - Cortex no Gyakushuu! features improved graphics and mechanics. Explore the localized Japanese version of this platforming masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-2---cortex-strikes-back', 'Playstation', 'Crash Bandicoot 2 - Cortex Strikes Back', '1997', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D platforming with sliding, crawling, and jetpack mechanics.', 'Collect all crystals in the warp rooms to stop a planetary threat.', 'The definitive sequel featuring smoother controls and larger levels.', 'Crash Bandicoot 2 - Cortex Strikes Back is a pinnacle of 3D platforming. Master new moves and explore diverse environments to defeat Dr. Cortex.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-3---buttobi!-sekai-isshuu-japan', 'Playstation', 'Crash Bandicoot 3 - Buttobi! Sekai Isshuu (Japan)', '1998', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D platforming with time-traveling themes and vehicle stages.', 'Collect crystals across history to thwart Uka Uka and Cortex.', 'The localized Japanese version of the third Crash Bandicoot game.', 'Crash Bandicoot 3 - Buttobi! Sekai Isshuu offers high-speed action and platforming. Play the Japanese release of the most successful entry in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-3---warped-europe-enfrdeesit', 'Playstation', 'Crash Bandicoot 3 - Warped (Europe) (En,Fr,De,Es,It)', '1998', 'Platformer', 'Naughty Dog', '1', '3D platformer', '3D platforming with multi-language support and time-travel levels.', 'Prevent the world''s destruction by collecting power crystals.', 'The European PAL version of the third game featuring several languages.', 'Crash Bandicoot 3 - Warped for Europe is the complete time-traveling adventure. Includes localized text and voices for a wide variety of European regions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-carnival-japan', 'Playstation', 'Crash Bandicoot Carnival (Japan)', '2000', 'Party', 'SCE Japan Studio', '4', 'Party minigames', '4-player party game featuring mini-games and arena battles.', 'Outscore opponents in various competitive challenges.', 'The Japanese version of the party spin-off, Crash Bash.', 'Crash Bandicoot Carnival brings the Wumpa crew together for chaotic fun. Play the Japanese edition of this multiplayer mini-game collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bandicoot-racing-japan', 'Playstation', 'Crash Bandicoot Racing (Japan)', '1999', 'Racing', 'Naughty Dog', '2', 'Arcade kart racing', 'Kart racing with weaponized power-ups and drifting mechanics.', 'Win the trophy races to save Earth from Nitros Oxide.', 'The Japanese release of the legendary kart racer, CTR.', 'Crash Bandicoot Racing delivers high-speed competitive fun. Experience the Japanese version of the game that redefined the kart racing genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-bash', 'Playstation', 'Crash Bash', '2000', 'Party', 'Eurocom', '4', 'Party minigames', '4-player party game with arena-based combat and puzzles.', 'Win a series of mini-games to prove the superiority of good or evil.', 'A chaotic multiplayer experience featuring the Crash cast.', 'Crash Bash is the ultimate party title for PS1. Compete in tank battles, pogo races, and crate throwing in this high-energy local multiplayer game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crash-team-racing', 'Playstation', 'Crash Team Racing', '1999', 'Racing', 'Naughty Dog', '4', 'Arcade kart racing', 'High-speed kart racing with a deep drifting and boost system.', 'Defeat Nitros Oxide in the Adventure Mode to save the planet.', 'Often cited as the best kart racer of the 32-bit era.', 'Crash Team Racing (CTR) features tight controls and ingenious track design. Master the power-slide and use iconic weapons to dominate your friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creative-camp', 'Playstation', 'Creative Camp', '1996', 'Educational', 'Philips Interactive Media', '1', 'Creative educational', 'Creative educational software with various interactive activities.', 'Complete creative tasks and explore interactive environments.', 'An educational title designed to spark imagination in children.', 'Creative Camp offers a safe and fun digital space for kids. Engage in artistic activities and simple puzzles in this family-oriented software.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creative-isle', 'Playstation', 'Creative Isle', '1996', 'Educational', 'Philips Interactive Media', '1', 'Creative educational', 'Creative educational software focused on island exploration.', 'Solve interactive puzzles and engage in creative mini-games.', 'Part of a series of educational tools for the PlayStation.', 'Creative Isle provides a world of discovery for younger players. Build, draw, and explore a colorful digital island in this interactive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creative-journey-1', 'Playstation', 'Creative Journey 1', '1996', 'Educational', 'Philips Interactive Media', '1', 'Creative educational', 'Story-driven educational tool for children''s development.', 'Follow the journey and participate in creative problem-solving.', 'A narrative-based educational game for the early PS1.', 'Creative Journey 1 combines storytelling with interactive learning. Perfect for young players looking for an engaging and educational adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creatures', 'Playstation', 'Creatures', '1996', 'Simulation', 'Creature Labs', '1', 'Artificial life simulation', 'Artificial life simulation featuring small creatures called Norns.', 'Hatch and raise Norns while teaching them how to survive.', 'A complex biological simulation that lives and breathes.', 'Creatures for PS1 is a unique digital pet experience. Manage the genetics and behavior of your Norns in this deep, ecosystem-based simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('creatures-raised-in-space', 'Playstation', 'Creatures Raised in Space', '1998', 'Simulation', 'Creature Labs', '1', 'Artificial life simulation', 'Artificial life simulation set in a high-tech space station.', 'Raise and train Norns in a futuristic environment.', 'A sci-fi themed follow-up to the original life sim game.', 'Creatures Raised in Space takes the biological simulation to the stars. Teach your Norns to survive the challenges of a digital space station.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crime-killer', 'Playstation', 'Crime Killer', '1998', 'Action', 'Konami', '2', 'Third-person vehicular combat', 'Vehicular combat and racing in a futuristic city.', 'Eliminate criminals or win races using weaponized patrol cars.', 'A high-speed mix of "Twisted Metal" and "Need for Speed."', 'Crime Killer puts you in the driver''s seat of futuristic law enforcement. Use an array of heavy weapons to clean up the streets in this action-heavy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crisis-beat', 'Playstation', 'Crisis Beat', '1997', 'Action', 'Sony Interactive Studios', '2', 'Beat ''em up', '3D beat ''em up featuring two playable characters on a ship.', 'Fight through terrorists to regain control of a cruise liner.', 'A cinematic brawler with fast-paced combat and environmental hazards.', 'Crisis Beat offers intense 3D fighting action. Choose your hero and take down hordes of enemies in this high-stakes maritime adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('critical-depth', 'Playstation', 'Critical Depth', '1999', 'Shooter', 'SingleTrac', '2', 'Submarine combat shooter', 'Underwater vehicular combat from the creators of Twisted Metal.', 'Collect the mysterious spheres at the bottom of the ocean.', 'A dark, atmospheric combat game set in the deep sea.', 'Critical Depth brings the carnage of car combat to the ocean floor. Choose a faction and blast your way through underwater canyons to claim the prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('croc---legend-of-the-gobbos', 'Playstation', 'Croc - Legend Of The Gobbos', '1997', 'Platformer', 'Argonaut Games', '1', '3D platformer', '3D platformer featuring a small crocodile and rescue missions.', 'Rescue your friends, the Gobbos, and defeat Baron Dante.', 'A charming early 3D platformer with unique tank controls.', 'Croc - Legend Of The Gobbos is a colorful journey through 3D worlds. Master the tail swipe and find all the hidden Gobbos in this classic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('croc-2', 'Playstation', 'Croc 2', '1999', 'Platformer', 'Argonaut Games', '1', '3D platformer', 'Refined 3D platforming with hub worlds and better movement.', 'Stop the return of Baron Dante and find Croc''s long-lost parents.', 'An expanded sequel with more variety and improved visuals.', 'Croc 2 takes the adventure further with diverse missions and vibrant graphics. Help the Croc find his family in this expansive platforming follow-up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crossroad-crisis', 'Playstation', 'Crossroad Crisis', '1998', 'Action', 'Titus Interactive', '2', 'Third-person action', 'Tile-sliding puzzle game with a focus on pathfinding.', 'Slide blocks to create a safe path for characters to cross.', 'A brain-teasing puzzle game that requires quick thinking.', 'Crossroad Crisis is a test of logic and speed. Prevent your characters from falling by constantly rearranging the road in this addictive puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crusaders-of-might-and-magic', 'Playstation', 'Crusaders of Might and Magic', '1999', 'Action', '3DO', '1', 'Action RPG', 'Third-person action-RPG with a focus on melee combat.', 'Defeat the legions of the undead to save the kingdom.', 'An action-oriented spin-off of the famous Might and Magic series.', 'Crusaders of Might and Magic features dark dungeons and epic combat. Use swords and sorcery to fight your way through a fantasy world on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces', 'Playstation', 'CT Special Forces', '1998', 'Action', 'Lightweight', '1', 'Run and gun', 'Side-scrolling run-and-gun action with multiple protagonists.', 'Infiltrate enemy bases and eliminate global terrorist threats.', 'A handheld-style shooter ported to the big screen.', 'CT Special Forces delivers classic 2D shooting action. Use stealth and firepower to complete dangerous missions in this high-intensity war game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-2---back-to-hell', 'Playstation', 'CT Special Forces 2 - Back to Hell', '2000', 'Action', 'Lightweight', '1', 'Run and gun', 'Side-scrolling run-and-gun with more levels and weapons.', 'Stop a new wave of global terror across various military theaters.', 'An explosive sequel with improved mechanics and larger bosses.', 'CT Special Forces 2 - Back to Hell ramps up the action. Experience harder levels and more intense fire-fights in this hardcore 2D shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ct-special-forces-3---bioterror', 'Playstation', 'CT Special Forces 3 - Bioterror', '2002', 'Action', 'Lightweight', '1', 'Run and gun', 'Side-scrolling run-and-gun action focusing on biological threats.', 'Neutralize a terrorist cell before they release a deadly virus.', 'The third entry in the series with more modern graphics and tech.', 'CT Special Forces 3 - Bioterror brings the elite squad back. Fight through infected zones and use advanced gadgets to save the world from a plague.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cubix-robots-for-everyone-racen-robots', 'Playstation', 'Cubix Robots for Everyone Race''n Robots', '2002', 'Racing', 'Blitz Games', '2', 'Arcade racing', 'Racing game based on the Cubix animated TV series.', 'Win races and collect parts to upgrade your robot racer.', 'A family-friendly kart racer with a robotic theme.', 'Cubix Robots for Everyone Race''n Robots is fun for fans of the show. Customize your bot and compete on vibrant tracks in this colorful racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-org', 'Playstation', 'Cyber Org', '1999', 'Action', 'Exact', '1', 'First-person action', '3D action-adventure featuring futuristic combat and puzzles.', 'Navigate through space stations and fight robotic enemies.', 'A sci-fi adventure from Square with a unique aesthetic.', 'Cyber Org offers a blend of action and exploration in a high-tech world. Experience a cinematic sci-fi story with rhythmic combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-sled', 'Playstation', 'Cyber Sled', '1995', 'Action', 'Namco', '2', 'Arcade vehicular combat', 'Futuristic tank combat based on the Namco arcade game.', 'Destroy all rival hover-tanks in a high-speed arena.', 'A fast-paced vehicular combat game with smooth 3D movement.', 'Cyber Sled brings arcade-style tank dueling to the PS1. Use agility and firepower to outmaneuver opponents in neon-lit arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyber-speed', 'Playstation', 'Cyber Speed', '1996', 'Racing', 'Sony Interactive Studios', '2', 'Futuristic racing', 'High-speed futuristic racing on plasma-based tracks.', 'Win races using experimental vehicles with magnetic physics.', 'A visually abstract and incredibly fast racing experience.', 'Cyber Speed offers a unique take on futuristic driving. Master the "plasma-cable" mechanic to take corners at impossible speeds in this 32-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cyberbots---full-metal-madness', 'Playstation', 'Cyberbots - Full Metal Madness', '1995', 'Fighting', 'Capcom', '2', '2D fighting', '2D fighting game featuring giant customizable mechs.', 'Defeat other robots in a tournament to prove your pilot skills.', 'A technical mech-fighter from Capcom with stunning sprites.', 'Cyberbots - Full Metal Madness features massive robot combat. Choose your pilot and customize your mech''s limbs to create the ultimate fighting machine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution', 'Playstation', 'Dance Dance Revolution', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based dancing game using a specialized peripheral.', 'Step on the arrows in time with the music to achieve a high score.', 'The foundational home version of the legendary dancing series.', 'Dance Dance Revolution brings the arcade floor to your home. Master the beats and burn calories in the game that started the dance craze.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution---disney-mix', 'Playstation', 'Dance Dance Revolution - Disney Mix', '2000', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based dancing game featuring Disney music and characters.', 'Step on the arrows in time with remixed Disney classics.', 'A magical crossover of DDR gameplay and iconic Disney themes.', 'Dance Dance Revolution - Disney Mix brings the magic of Disney to the dance floor. Perfect for families, it features high-energy remixes of beloved songs and classic characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution---extra-mix', 'Playstation', 'Dance Dance Revolution - Extra Mix', '2001', 'Music', 'Konami', '2', 'Rhythm game', 'Advanced rhythm gameplay with a massive collection of tracks.', 'Achieve high scores on a wide variety of exclusive arcade mixes.', 'A comprehensive DDR expansion with a huge song selection.', 'Dance Dance Revolution - Extra Mix offers the ultimate challenge for rhythm fans. Master complex patterns and enjoy a diverse soundtrack of high-bpm dance hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution-japan', 'Playstation', 'Dance Dance Revolution (Japan)', '1998', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based dancing game using a specialized dance pad.', 'Follow the arrow prompts to keep the rhythm and clear the stage.', 'The original Japanese home version of the arcade sensation.', 'Experience the game that started it all. Dance Dance Revolution (Japan) brings the authentic arcade experience to your PlayStation with a classic set of J-pop and dance tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution-3rd-mix', 'Playstation', 'Dance Dance Revolution 3rd Mix', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm gameplay featuring the "Non-Stop" mode and new tracks.', 'Clear consecutive songs without stopping to prove your stamina.', 'The third major evolution of the DDR series with more hits.', 'Dance Dance Revolution 3rd Mix features an expanded roster of songs and refined visuals. Perfect your timing and master the new modes in this rhythm staple.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution-4th-mix', 'Playstation', 'Dance Dance Revolution 4th Mix', '2000', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm gameplay with updated interface and smoother animations.', 'Hit the arrows perfectly to unlock hidden songs and challenges.', 'The fourth installment featuring modern dance and pop hits.', 'Dance Dance Revolution 4th Mix delivers a sleek, updated experience. With a fresh song list and improved engine, it is a peak era title for dance simulation fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution-5th-mix', 'Playstation', 'Dance Dance Revolution 5th Mix', '2001', 'Music', 'Konami', '2', 'Rhythm game', 'High-performance rhythm gameplay with a massive technical soundtrack.', 'Master the most difficult tracks in the series'' PS1 history.', 'The final numbered DDR entry for the original PlayStation.', 'Dance Dance Revolution 5th Mix pushes the 32-bit hardware to the limit. Enjoy high-fidelity visuals and a soundtrack designed for hardcore dancers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dance-dance-revolution-konamix', 'Playstation', 'Dance Dance Revolution Konamix', '2002', 'Music', 'Konami', '2', 'Rhythm game', 'Compilation of the best DDR tracks from various arcade releases.', 'Dance through a curated list of Konami''s greatest rhythm hits.', 'A massive "best-of" collection released for the Western market.', 'Dance Dance Revolution Konamix is the ultimate anthology for PS1. Featuring over 50 tracks, it’s a comprehensive journey through the early history of dance gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('danger-girl', 'Playstation', 'Danger Girl', '2000', 'Action', 'N-Forge', '1', 'Third-person action', 'Third-person action-adventure featuring stealth and shooting.', 'Infiltrate enemy bases and stop a global terrorist organization.', 'A stylish action game based on the popular comic book series.', 'Danger Girl brings the comic world to life. Play as elite female spies and use high-tech gadgets and weapons to save the world in this cinematic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dare-devil-derby-3d', 'Playstation', 'Dare Devil Derby 3D', '1997', 'Racing', 'Viewpoint', '2', 'Arcade racing', 'Arcade-style racing with 3D cartoon visuals and physics.', 'Win races across wacky tracks while avoiding environmental hazards.', 'A quirky and fast-paced racer with a focus on fun physics.', 'Dare Devil Derby 3D offers chaotic racing action. Choose from a variety of odd vehicles and master the loops and jumps in this vibrant arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darklight-conflict', 'Playstation', 'Darklight Conflict', '1997', 'Shooter', 'Shiny Entertainment', '2', 'Space combat shooter', 'First-person space combat simulation with large fleet battles.', 'Pilot a starfighter to defend your home world from invaders.', 'A dark, atmospheric space shooter with a deep story.', 'Darklight Conflict delivers intense dogfights and cinematic space warfare. Manage your energy and weapons to survive massive galactic encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darkstalkers-3', 'Playstation', 'Darkstalkers 3', '1997', 'Fighting', 'Capcom', '2', '2D fighting', '2D fighting game featuring legendary monsters and ghouls.', 'Defeat all supernatural rivals to rule the night.', 'A high-energy Capcom fighter with fluid 2D animation.', 'Darkstalkers 3 features an incredible roster of classic monsters. Master the "Dark Force" system and unleash devastating combos in this technical 2D masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darkstalkers:-the-night-warriors', 'Playstation', 'Darkstalkers: The Night Warriors', '1995', 'Fighting', 'Capcom', '2', '2D fighting', '2D fighting game where monsters and mythical beings collide.', 'Win the tournament to become the lord of the Night Warriors.', 'The foundational entry in Capcom''s gothic fighting series.', 'Darkstalkers: The Night Warriors brings unique mechanics and stunning character design to the PS1. Experience the original battles of Morrigan and Felicia.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('darkstone', 'Playstation', 'Darkstone', '1999', 'RPG', 'Microids', '1', 'Action RPG', 'Action-RPG with procedurally generated dungeons and 3D graphics.', 'Defeat the ancient dragon Drakk and save the world from darkness.', 'A deep, "Diablo-style" RPG with four character classes.', 'Darkstone offers endless replayability with its randomized levels. Explore dangerous dungeons, learn powerful magic, and defeat evil in this expansive 3-D RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dave-mirra-freestyle-bmx', 'Playstation', 'Dave Mirra Freestyle BMX', '2000', 'Sports', 'Z-Axis', '2', 'Extreme sports', 'Extreme sports simulation featuring professional BMX riding.', 'Complete trick-based objectives to unlock new gear and bikes.', 'The premier BMX title for PS1 starring a sports legend.', 'Dave Mirra Freestyle BMX delivers high-flying action and a killer soundtrack. Master the "S.K.A.T.E" style objectives on two wheels in this classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dave-mirra-freestyle-bmx:-maximum-remix', 'Playstation', 'Dave Mirra Freestyle BMX: Maximum Remix', '2001', 'Sports', 'Z-Axis', '2', 'Extreme sports', 'Enhanced BMX simulation with additional levels and riders.', 'Conquer every park and complete all challenges to become a legend.', 'The definitive version of the Dave Mirra BMX experience.', 'Maximum Remix takes the original game and adds more content, more tricks, and more bikes. It’s the ultimate package for fans of freestyle sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('david-beckham-soccer', 'Playstation', 'David Beckham Soccer', '1998', 'Sports', 'Rage Software', '2', 'Soccer simulation', '3D soccer simulation featuring the world-famous player.', 'Lead your team to victory in global tournaments and leagues.', 'An accessible and polished football game with a famous face.', 'David Beckham Soccer offers smooth controls and realistic match atmospheres. Play through his career or lead your favorite international team to the cup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('davilex-compilation', 'Playstation', 'Davilex Compilation', '1999', 'Compilation', 'Davilex', '1', 'Game compilation', 'Compilation of high-speed racing and action games from Davilex.', 'Win illegal street races and escape the law across Europe.', 'A collection of the "Raser" series and other European hits.', 'Davilex Compilation brings together the best of highway racing. Experience high-speed chases and urban driving in this multi-game package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-ball-zone', 'Playstation', 'Dead Ball Zone', '1998', 'Sports', 'Beyond Games', '2', 'Futuristic sports', 'Violent sports hybrid featuring futuristic football and combat.', 'Score goals while brutally attacking the opposing team.', 'A gritty, futuristic sports game where anything goes.', 'Dead Ball Zone is a dark take on athletics. Use combat moves and speed to dominate the field in this high-intensity, futuristic contact sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-in-the-water', 'Playstation', 'Dead in the Water', '1998', 'Shooter', 'Creative Differences', '2', 'Naval combat shooter', 'Vehicular combat and racing set in aquatic environments.', 'Destroy rivals and win races using weaponized speedboats.', 'An explosive "Twisted Metal" style game on the water.', 'Dead in the Water delivers high-speed nautical carnage. Master your boat''s handling and unleash missiles to be the last one floating.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dead-or-alive', 'Playstation', 'Dead or Alive', '1997', 'Fighting', 'Team Ninja', '2', '3D fighting', '3D weapon-based fighting game with a focus on counters.', 'Win the tournament to claim the prize and prove your strength.', 'A high-speed fighter known for its "Danger Zone" arenas.', 'Dead or Alive brings its signature counter-system to the PS1. Experience fast-paced 3D combat and interactive environments in this legendary brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deadheat-road', 'Playstation', 'Deadheat Road', '1996', 'Racing', 'Tunnel Vision Games', '2', 'Arcade racing', 'Arcade-style racing with a focus on drifting and speed.', 'Outpace rivals on high-speed Japanese highways.', 'A classic "highway racer" with a focus on the midnight car culture.', 'Deadheat Road offers intense urban racing. Master your car’s tuning and drift through tight corners to become the king of the highway.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deception-iii:-dark-delusion', 'Playstation', 'Deception III: Dark Delusion', '1999', 'Strategy', 'Tecmo', '1', 'Tactical strategy', 'Tactical trap-setting game with a dark fantasy narrative.', 'Defend your castle by placing lethal traps to kill invaders.', 'A unique "anti-RPG" where you play as the dungeon master.', 'Deception III: Dark Delusion is a game of strategy and cruelty. Create complex trap combos to stop your enemies in this deep psychological thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defcon-5---peace-has-a-price', 'Playstation', 'Defcon 5 - Peace Has a Price', '1995', 'Shooter', 'Millennium Interactive', '1', 'First-person shooter', 'First-person strategy and action set on a deep-space station.', 'Survive an alien attack and manage the station''s security.', 'A cinematic mix of FMV adventure and strategic action.', 'Defcon 5 - Peace Has a Price offers a tense, atmospheric experience. Use the station’s systems to defend against an unknown threat in this sci-fi classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('delta-force---urban-warfare', 'Playstation', 'Delta Force - Urban Warfare', '2001', 'Shooter', 'Rebellion Developments', '1', 'Tactical shooter', 'First-person tactical shooter with realistic military objectives.', 'Neutralize terrorists in urban environments using precision.', 'A gritty, realistic shooter focused on modern warfare.', 'Delta Force - Urban Warfare brings elite military tactics to the PS1. Use stealth and high-tech weaponry to complete high-stakes missions in hostile cities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demolition-racer', 'Playstation', 'Demolition Racer', '1998', 'Racing', 'Infogrames', '2', 'Arcade racing', 'High-octane racing with a heavy focus on car destruction.', 'Win the race while smashing your rivals into scrap metal.', 'A fast-paced racer that rewards aggressive driving.', 'Demolition Racer combines speed with carnage. Earn points for spectacular crashes and aim for the podium in this chaotic destruction derby.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('densha-de-go!-japan', 'Playstation', 'Densha de Go! (Japan)', '1997', 'Simulation', 'Taito', '1', 'Train simulation', 'Realistic train driving simulation based on Japanese railways.', 'Drive trains with precision, following schedules and signals.', 'A cult-classic simulation that captures the art of the rails.', 'Densha de Go! offers a unique and relaxing challenge. Master the controls of various Japanese trains in this beautifully detailed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('descent', 'Playstation', 'Descent', '1995', 'Shooter', 'Parallax Software', '2', 'First-person shooter', '360-degree first-person shooter set in subterranean mines.', 'Navigate 3D environments to destroy the reactor and escape.', 'A revolutionary FPS with total freedom of movement.', 'Descent redefines the shooter genre. Fly in any direction through winding tunnels and engage in intense combat against robotic drones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('descent-maximum', 'Playstation', 'Descent Maximum', '1996', 'Shooter', 'Parallax Software', '2', 'First-person shooter', 'Enhanced 360-degree shooter with new levels and enemies.', 'Complete high-stakes missions in deep-space environments.', 'A PlayStation-exclusive follow-up to the original Descent.', 'Descent Maximum offers more of the mind-bending 3D action the series is known for. Navigate complex vertical maps and master the art of 6-degree combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destrega', 'Playstation', 'Destrega', '1998', 'Action', 'Sony Interactive Studios', '2', '3D arena combat', '3D tactical combat game with magic and long-range attacks.', 'Defeat enemies in a large arena using strategic projectiles.', 'A unique take on the fighting genre from the creators of Dynasty Warriors.', 'Destrega focuses on long-range magical duels. Master your positioning and timing to outwit opponents in this innovative 3D battler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destruction-derby', 'Playstation', 'Destruction Derby', '1995', 'Racing', 'Psygnosis', '2', 'Demolition racing', 'Vehicular combat and racing focused on total car destruction.', 'Smash your car into opponents to be the last one running.', 'The foundational game of the car-crashing genre.', 'Destruction Derby delivers pure automotive mayhem. Compete in arenas or races where wrecking your rivals is just as important as speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destruction-derby-2', 'Playstation', 'Destruction Derby 2', '1996', 'Racing', 'Psygnosis', '2', 'Demolition racing', 'Refined car destruction with better physics and larger tracks.', 'Win the championship by destroying rivals and racing fast.', 'A high-performance sequel that improved every aspect of the original.', 'Destruction Derby 2 features massive jumps and more detailed crashes. It is the definitive car combat experience for the original PlayStation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('destruction-derby-raw', 'Playstation', 'Destruction Derby Raw', '2000', 'Racing', 'Kalisto Entertainment', '2', 'Demolition racing', 'Arcade-style vehicular combat with a gritty urban theme.', 'Outlast your rivals in a series of brutal demolition events.', 'A late-era entry in the series with more aggressive gameplay.', 'Destruction Derby Raw brings the carnage to new environments. With updated graphics and more cars, it’s a high-octane farewell to the series on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('detana-twinbee-yahho!-deluxe-pack', 'Playstation', 'Detana Twinbee Yahho! Deluxe Pack', '1996', 'Shooter', 'Konami', '2', 'Arcade shooter', 'Collection featuring two classic "Twinbee" arcade shooters.', 'Blast through colorful levels to save the kingdom from evil.', 'A vibrant and cute "shmup" package with high-quality ports.', 'Detana Twinbee Yahho! Deluxe Pack offers charming arcade action. Experience two of Konami’s most beautiful shooters in one explosive collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devil-dice', 'Playstation', 'Devil Dice', '1998', 'Puzzle', 'Shift', '2', 'Dice puzzle', 'Rhythmic puzzle game involving rolling dice to clear the board.', 'Match dice faces to clear them and score high combos.', 'A unique and incredibly addictive "action-puzzle" title.', 'Devil Dice challenges your spatial logic and speed. Roll your way through various modes in one of the most original puzzle games on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dexters-laboratory:-mandarks-lab?', 'Playstation', 'Dexter''s Laboratory: Mandark''s Lab?', '1998', 'Puzzle', 'Twilight Games', '1', 'Puzzle platformer', 'Mini-game collection based on the hit Cartoon Network show.', 'Complete various scientific challenges to defeat Dexter''s rival.', 'A fun and humorous adventure for fans of the show.', 'Dexter''s Laboratory: Mandark''s Lab brings the humor of the lab home. Solve puzzles and win mini-games to prove Dexter’s genius once and for all.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('diablo', 'Playstation', 'Diablo', '1997', 'RPG', 'Blizzard North', '1', 'Action RPG', 'Action-RPG with dark themes and deep dungeon exploration.', 'Descend into the cathedral to find and destroy the Lord of Terror.', 'The legendary PC classic ported with a new control scheme.', 'Diablo for PS1 brings the dark world of Tristram to your TV. Choose your hero and survive the depths of hell in this landmark gothic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-hard-trilogy', 'Playstation', 'Die Hard Trilogy', '1996', 'Action', 'NeverSoft', '2', 'Action compilation', 'Multi-genre action: third-person shooter, light-gun shooter, and driving.', 'Stop terrorists across three different scenarios based on the films.', 'Three games in one, offering a complete Die Hard movie experience.', 'Die Hard Trilogy for PS1 delivers non-stop action. Experience an innovative mix of genres, from clearing Nakatomi Plaza to high-speed chases in NYC.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('die-hard-trilogy-2---viva-las-vegas-usa', 'Playstation', 'Die Hard Trilogy 2 - Viva Las Vegas (USA)', '2000', 'Action', 'NeverSoft', '2', 'Action adventure', 'Hybrid action game featuring shooting, driving, and arcade segments.', 'Stop a nuclear threat in Las Vegas as John McClane.', 'An explosive sequel with improved graphics and diverse missions.', 'Die Hard Trilogy 2 - Viva Las Vegas brings the cinematic thrill to the desert. Master different gameplay styles to thwart a global terrorist plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-digital-card-battle', 'Playstation', 'Digimon Digital Card Battle', '2000', 'Card game', 'Bandai', '2', 'Card battle game', 'Strategic card-based combat with Digimon-themed decks.', 'Win the Card Battle tournament to become the 7th Great Card Player.', 'A deep tactical card game featuring over 300 Digimon characters.', 'Digimon Digital Card Battle offers addictive deck-building strategy. Battle through the Digital World and evolve your cards to defeat powerful opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-rumble-arena', 'Playstation', 'Digimon Rumble Arena', '2001', 'Fighting', 'Bandai', '2', 'Arena fighting', '2.5D arena-based fighting game with environmental hazards.', 'Defeat all opponents in the tournament to become the champion.', 'A fast-paced "Super Smash Bros" style fighter starring Digimon.', 'Digimon Rumble Arena features high-energy combat and transformations. Play as your favorite Digimon and use unique special moves in chaotic arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world-europe', 'Playstation', 'Digimon World (Europe)', '2000', 'RPG', 'BEC', '1', 'Monster-raising RPG', 'Life simulation RPG with monster raising and town building.', 'Raise a Digimon partner and convince others to return to File City.', 'A deep and unique RPG focused on the bond with your Digimon.', 'Digimon World (Europe) is a cult classic. Train, feed, and evolve your partner to explore the island and rebuild the digital community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world-usa', 'Playstation', 'Digimon World (USA)', '2000', 'RPG', 'BEC', '1', 'Monster-raising RPG', 'Life simulation RPG with monster raising and town building.', 'Raise a Digimon partner and convince others to return to File City.', 'A deep and unique RPG focused on the bond with your Digimon.', 'Digimon World (USA) delivers the definitive monster-raising experience. Master the complex evolution system to save the Digital World from decay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world-2', 'Playstation', 'Digimon World 2', '2000', 'RPG', 'BEC', '1', 'Dungeon-crawling RPG', 'Dungeon crawler RPG with turn-based combat and tank movement.', 'Join a Guard Team to explore domains and stop evil Digimon.', 'A 3D dungeon explorer with a focus on party-based combat.', 'Digimon World 2 expands the series with strategic exploration. Drive your Digi-Beetle through dangerous domains and recruit allies for tactical battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('digimon-world-3', 'Playstation', 'Digimon World 3', '2002', 'RPG', 'BEC', '1', 'JRPG', 'Traditional turn-based JRPG with a vast overworld and online theme.', 'Stop a cyber-terrorist organization within the Digimon Online game.', 'A massive RPG with three-on-three battles and deep customization.', 'Digimon World 3 offers a classic JRPG journey. Explore two distinct worlds, train your team, and uncover a conspiracy in this expansive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-crisis', 'Playstation', 'Dino Crisis', '1999', 'Horror', 'Capcom', '1', 'Survival horror', 'Third-person survival horror with "tank controls" and puzzles.', 'Survive a prehistoric outbreak and escape the Ibis Island facility.', 'A tense "Resident Evil" style game but with deadly dinosaurs.', 'Dino Crisis redefines survival horror with 3D environments. Manage your resources and outsmart fast, intelligent predators in this Capcom masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-crisis-demo', 'Playstation', 'Dino Crisis (Demo)', '1999', 'Horror', 'Capcom', '1', 'Survival horror', 'Third-person survival horror trial version with limited gameplay.', 'Experience the opening sections of the dinosaur-infested facility.', 'A playable preview of the highly anticipated dinosaur horror game.', 'The Dino Crisis Demo offers a glimpse into the terror. Test your survival skills against a Raptor in this rare collector''s preview.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dino-crisis-ii', 'Playstation', 'Dino Crisis II', '2000', 'Horror', 'Capcom', '1', 'Survival horror', 'Action-oriented third-person shooter with fixed camera angles.', 'Kill dinosaurs to earn points and find a way back to the present.', 'A high-octane sequel that shifts focus from horror to combat.', 'Dino Crisis II delivers relentless arcade-style action. Use a massive arsenal to blast through swarms of dinosaurs in this fast-paced jungle adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-a-bugs-life---disneys-activity-centre-europe', 'Playstation', 'Disney-Pixar A Bug''s Life - Disney''s Activity Centre (Europe)', '1999', 'Educational', 'Traveller''s Tales', '1', 'Educational activity', 'Collection of educational mini-games and creative activities.', 'Complete various tasks based on the world of Flik the ant.', 'A family-friendly activity center based on the Pixar film.', 'Disney-Pixar A Bug''s Life - Disney''s Activity Centre offers puzzles and games. Perfect for kids to interact with their favorite characters in a creative way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-monsters-inc---scream-team-usa', 'Playstation', 'Disney-Pixar Monsters, Inc. - Scream Team (USA)', '2001', 'Platformer', 'Traveller''s Tales', '2', '3D platformer', '3D platformer featuring exploration and "scaring" mechanics.', 'Complete training at Monsters, Inc. to become a Top Scarer.', 'A charming 3D adventure featuring Mike and Sulley.', 'Monsters, Inc. - Scream Team takes you to Scare Island. Use unique character abilities to collect screams and master the art of scaring in this Pixar hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disney-pixar-toy-story-racer-usa', 'Playstation', 'Disney-Pixar Toy Story Racer (USA)', '2001', 'Racing', 'Traveller''s Tales', '2', 'Arcade kart racing', 'High-speed kart racing with various Pixar characters and tracks.', 'Win the championship to prove you are the fastest toy on the track.', 'A competitive and vibrant racer featuring the Toy Story cast.', 'Toy Story Racer delivers tight racing mechanics on the PS1. Compete across diverse movie-inspired locations with gadgets and high-speed thrills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-aladdin-in-nasiras-revenge', 'Playstation', 'Disney''s Aladdin in Nasira''s Revenge', '2000', 'Platformer', 'Argonaut Games', '1', '3D platformer', '3D platformer with combat, puzzles, and magic lamp abilities.', 'Stop the evil Nasira from resurrecting Jafar in Agrabah.', 'A colorful adventure featuring Aladdin, Abu, and the Genie.', 'Disney''s Aladdin in Nasira''s Revenge brings the movie magic to life. Solve puzzles and fight guards in this vibrant 3D platforming journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-atlantis---the-lost-empire', 'Playstation', 'Disney''s Atlantis - The Lost Empire', '2001', 'Action', 'Eurocom', '2', 'Action adventure', 'Third-person action-adventure featuring diverse mission types.', 'Find the lost city of Atlantis using the Shepherd''s Journal.', 'A cinematic tie-in featuring vehicle levels and exploration.', 'Disney''s Atlantis - The Lost Empire follows the epic film''s plot. Join Milo and the crew to uncover the secrets of a submerged civilization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-dinosaur-usa', 'Playstation', 'Disney''s Dinosaur (USA)', '2000', 'Platformer', 'Artdink', '1', '3D platformer', '3D action-adventure with a top-down perspective and puzzles.', 'Guide Aladar and his friends to the safety of the Breeding Grounds.', 'A mission-based adventure based on the CGI Disney film.', 'Disney''s Dinosaur offers strategic gameplay and diverse environments. Protect your herd from predators and environmental hazards in this prehistoric quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-donald-duck---goin-quackers', 'Playstation', 'Disney''s Donald Duck - Goin'' Quackers', '2000', 'Platformer', 'Ubi Soft', '2', '3D platformer', '3D platformer with high-speed "crash-style" corridor levels.', 'Rescue Daisy Duck and defeat Merlock in his secret temple.', 'A fast-paced and polished platformer starring Donald Duck.', 'Disney''s Donald Duck - Goin'' Quackers features vibrant 3D graphics. Master the frantic gameplay and save Daisy in this high-energy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-goofys-fun-house-usa', 'Playstation', 'Disney''s Goofy''s Fun House (USA)', '2001', 'Adventure', 'Runecraft', '1', 'Children''s adventure', 'Mini-game collection and exploration within Goofy''s mansion.', 'Explore the house and complete various fun activities with Goofy.', 'A lighthearted and interactive game for younger children.', 'Disney''s Goofy''s Fun House is packed with classic Disney cartoons and mini-games. A perfect, safe experience for fans of the "Goof" himself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-hercules', 'Playstation', 'Disney''s Hercules', '1997', 'Platformer', 'Tiertex', '1', '2D platformer', '2D side-scrolling platformer with a distinct artistic style.', 'Battle through mythological trials to become a true hero.', 'A beautiful and challenging platformer based on the movie.', 'Disney''s Hercules brings the legendary hero to the PS1. Fight titans and monsters in this visually stunning and action-packed 2D classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-peter-pan-in-return-to-neverland', 'Playstation', 'Disney''s Peter Pan in Return to Neverland', '2002', 'Platformer', 'Disney Interactive', '1', '2D platformer', '3D platformer featuring flight and exploration mechanics.', 'Stop Captain Hook and his pirates to save Neverland.', 'A magical adventure based on the sequel to the classic film.', 'Disney''s Peter Pan in Return to Neverland lets you fly through the skies. Collect items and outsmart the pirates in this enchanting 3D journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-poohs-party-game---in-search-of-the-treasure-usa', 'Playstation', 'Disney''s Pooh''s Party Game - In Search of the Treasure (USA)', '2001', 'Party', 'Disney Interactive', '4', 'Party board game', '4-player party game with various themed mini-games.', 'Win a series of challenges to find the hidden treasure.', 'A fun multiplayer experience featuring the Hundred Acre Wood crew.', 'Disney''s Pooh''s Party Game is perfect for family fun. Compete with friends in simple, engaging mini-games starring Winnie the Pooh and friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-story-studio---mulan', 'Playstation', 'Disney''s Story Studio - Mulan', '1999', 'Educational', 'Disney Interactive', '1', 'Story creation', 'Interactive storybook and creative software for children.', 'Follow Mulan''s story and participate in creative activities.', 'An educational and artistic tool based on the animated film.', 'Disney''s Story Studio - Mulan allows kids to experience the legend. Build creativity with painting, dress-up, and storytelling mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-tarzan-europe', 'Playstation', 'Disney''s Tarzan (Europe)', '1999', 'Platformer', 'Eurocom', '1', '2D platformer', '2.5D side-scrolling platformer with swinging and surfing levels.', 'Protect the jungle from hunters and become the king of the apes.', 'A high-quality platformer with impressive graphics and music.', 'Disney''s Tarzan brings the jungle to your console. Master the art of tree-surfing and vine-swinging in this definitive movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-the-emperors-new-groove', 'Playstation', 'Disney''s the emperor''s new groove', '2000', 'Platformer', 'Saffire', '1', '3D platformer', '3D platformer featuring Kuzco with humor and puzzles.', 'Reach the palace and turn back into a human before Yzma stops you.', 'A witty and fast-paced adventure based on the cult-classic film.', 'Disney''s the emperor''s new groove is a blast of comedy and action. Use Kuzco''s animal forms to solve puzzles and navigate vibrant levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-the-lion-king---simbas-mighty-adventure-usa', 'Playstation', 'Disney''s The Lion King - Simba''s Mighty Adventure (USA)', '2001', 'Platformer', 'Traveller''s Tales', '1', '2D platformer', '2.5D side-scrolling platformer following Simba''s life journey.', 'Defeat Scar and reclaim the pride lands as the rightful king.', 'A cinematic platformer featuring clips from the movie.', 'Simba''s Mighty Adventure covers both films in one game. Experience Simba''s growth from a cub to a king in this action-packed Disney title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-the-little-mermaid-ii', 'Playstation', 'Disney''s The Little Mermaid II', '2000', 'Platformer', 'Infogrames', '1', '2D platformer', 'Mini-game collection and interactive story based on the sequel.', 'Help Melody discover her mermaid heritage through various games.', 'A charming family-friendly title featuring under-the-sea fun.', 'Disney''s The Little Mermaid II offers puzzles and activities for kids. Explore the ocean and interact with favorite characters in this gentle adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-treasure-planet', 'Playstation', 'Disney''s Treasure Planet', '2002', 'Action', 'Bizarre Creations', '1', 'Action adventure', '3D platformer with exploration, combat, and hover-surfing.', 'Find the legendary Treasure Planet using the star map.', 'A sci-fi adventure based on the high-flying animated film.', 'Disney''s Treasure Planet delivers high-speed surfing and exploration. Join Jim Hawkins on a galactic quest to find the ultimate treasure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-winnie-the-pooh---kindergarten', 'Playstation', 'Disney''s Winnie the Pooh - Kindergarten', '2001', 'Educational', 'Disney Interactive', '1', 'Educational game', 'Educational software focused on kindergarten-level learning.', 'Complete various learning tasks with Winnie the Pooh.', 'A fun and educational tool for early childhood development.', 'Winnie the Pooh - Kindergarten makes learning fun. Explore the Hundred Acre Wood while building essential skills in math, reading, and logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disneys-winnie-the-pooh---preschool-usa', 'Playstation', 'Disney''s Winnie the Pooh - Preschool (USA)', '2001', 'Educational', 'Disney Interactive', '1', 'Educational game', 'Educational software focused on preschool-level learning.', 'Engage in simple activities to learn colors, shapes, and letters.', 'A gentle introduction to learning for the youngest players.', 'Disney''s Winnie the Pooh - Preschool offers a safe environment. Join Pooh and friends for interactive lessons designed for early development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disruptor', 'Playstation', 'Disruptor', '1996', 'Shooter', 'Insomniac Games', '1', 'First-person shooter', 'First-person shooter with psychic abilities and high-tech guns.', 'Stop a rogue psychic group from taking over the world.', 'An innovative FPS from the creators of Spyro the Dragon.', 'Disruptor combines intense shooting with unique psionic powers. Experience high-quality FMV cutscenes and fast-paced combat in this early PS1 hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('disruptor-usa', 'Playstation', 'Disruptor (USA)', '1996', 'Shooter', 'Insomniac Games', '1', 'First-person shooter', 'First-person shooter with psychic abilities and high-tech guns.', 'Stop a rogue psychic group from taking over the world.', 'An innovative FPS from the creators of Spyro the Dragon.', 'Disruptor (USA) delivers the same high-octane psychic warfare. Master your "Psion" abilities to dominate the battlefield in this cult-classic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dodonpachi', 'Playstation', 'DoDonPachi', '1997', 'Shooter', 'Cave', '2', 'Bullet hell shooter', 'Vertical bullet-hell shooter with intense enemy patterns.', 'Blast through waves of enemies to save the world from the DonPachi.', 'A legendary arcade port known for its high difficulty.', 'DoDonPachi is a masterpiece of the "shmup" genre. Master the scoring system and navigate through thousands of bullets in this intense arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doom', 'Playstation', 'Doom', '1995', 'Shooter', 'id Software', '2', 'First-person shooter', 'First-person shooter with a focus on exploration and survival.', 'Fight your way through Martian moons to defeat the legions of Hell.', 'A massive port featuring improved lighting and new levels.', 'Doom on PS1 is the ultimate console version. With atmospheric lighting and a creepy ambient soundtrack, it brings the classic FPS to a new level of horror.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---nobita-to-fukkatsu-no-hoshi-japan', 'Playstation', 'Doraemon - Nobita to Fukkatsu no Hoshi (Japan)', '1996', 'Adventure', 'Epoch', '1', 'Action adventure', '2D side-scrolling platformer with gadget-based puzzle solving.', 'Assist Nobita and friends in their space adventure using secret tools.', 'A charming platformer based on the iconic anime series.', 'Doraemon - Nobita to Fukkatsu no Hoshi brings the magic of the 4D pocket to PS1. Use various gadgets to overcome obstacles and save the day in this vibrant adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-2---sos!-otogi-no-kuni-japan', 'Playstation', 'Doraemon 2 - SOS! Otogi no Kuni (Japan)', '1998', 'Adventure', 'Epoch', '1', 'Action adventure', '3D platformer featuring exploration and diverse mini-games.', 'Journey through a fairy-tale world to rescue kidnapped friends.', 'An expansive sequel with colorful graphics and creative levels.', 'Doraemon 2 - SOS! Otogi no Kuni offers a delightful 3D world for fans. Explore magical landscapes and use classic gadgets in this family-friendly quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon-3---makai-no-dungeon-japan', 'Playstation', 'Doraemon 3 - Makai no Dungeon (Japan)', '2000', 'RPG', 'Epoch', '1', 'Dungeon crawler RPG', 'Turn-based roguelike dungeon crawler with randomized floors.', 'Explore the Demon World''s dungeon to find treasure and save the world.', 'A challenging "Mystery Dungeon" style RPG starring Doraemon.', 'Doraemon 3 - Makai no Dungeon features deep RPG mechanics and item management. Navigate perilous floors and battle monsters in this strategic spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon', 'Playstation', 'Double Dragon', '1995', 'Action', 'Technōs Japan', '2', 'Side-scrolling beat ''em up', 'Side-scrolling beat ''em up based on the 1994 movie.', 'Fight through street gangs to rescue Marian and defeat Shuko.', 'A weapon-based brawler with digitized character graphics.', 'Double Dragon for PS1 brings the cinematic fighting experience home. Choose your fighter and master martial arts in this gritty urban combat game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dracula---the-last-sanctuary-usa-disc-1', 'Playstation', 'Dracula - The Last Sanctuary (USA) (Disc 1)', '1999', 'Adventure', 'Index+', '1', 'Point-and-click adventure', 'Point-and-click horror adventure with cinematic pre-rendered scenes.', 'Track down Count Dracula to save your wife and end the curse.', 'A dark, puzzle-heavy sequel to Dracula: Resurrection.', 'Dracula - The Last Sanctuary (Disc 1) plunges you into a gothic nightmare. Solve intricate puzzles and explore eerie environments to defeat the Lord of Vampires.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dracula---the-last-sanctuary-usa-disc-2', 'Playstation', 'Dracula - The Last Sanctuary (USA) (Disc 2)', '1999', 'Adventure', 'Index+', '1', 'Point-and-click adventure', 'Point-and-click horror adventure with cinematic pre-rendered scenes.', 'Confront Dracula in his final lair to rescue Mina.', 'The concluding half of the atmospheric vampire-hunting saga.', 'Dracula - The Last Sanctuary (Disc 2) concludes the epic hunt. Face the ultimate evil in this narrative-driven adventure filled with suspense and mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-gt---final-bout', 'Playstation', 'Dragon Ball GT - Final Bout', '1997', 'Fighting', 'Tose', '2', '3D fighting', '3D fighting game featuring characters from the GT and Z eras.', 'Win the tournament and defeat powerful foes like Baby and Pan.', 'The first 3D Dragon Ball fighter with an iconic opening theme.', 'Dragon Ball GT - Final Bout offers explosive ki blasts and 3D combat. Master the "Build-up" mode to create the ultimate Saiyan warrior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z:-the-legend', 'Playstation', 'Dragon Ball Z: The Legend', '1996', 'Fighting', 'BEC', '2', '2D fighting', 'Fast-paced 2D team-based fighter with flight mechanics.', 'Relive the major battles of the Z series with a large roster.', 'A unique fighter focusing on aerial combat and team strategy.', 'Dragon Ball Z: The Legend features massive scale battles that mirror the anime. Control three fighters at once in intense, high-speed energy duels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z:-ultimate-battle-22', 'Playstation', 'Dragon Ball Z: Ultimate Battle 22', '1995', 'Fighting', 'Tose', '2', '2D fighting', '2D fighting game with hand-drawn sprites and cinematic attacks.', 'Defeat a roster of 22 (and hidden) fighters in the Tenkaichi Budokai.', 'A classic 2D brawler known for its expansive character list.', 'Dragon Ball Z: Ultimate Battle 22 brings the anime aesthetic to life. Unleash signature moves like the Kamehameha in this nostalgic fighting title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-valor-usa', 'Playstation', 'Dragon Valor (USA)', '1999', 'Action', 'Racjin', '1', 'Action adventure', '3D action-RPG featuring branching paths and monster hunting.', 'Slay the dragons and pass down your sword to future generations.', 'A unique multi-generational epic from the creators of SoulCalibur.', 'Dragon Valor offers high-speed hack-and-slash combat. Your choices determine which descendants continue the quest to rid the world of dragons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragstars', 'Playstation', 'Dragstars', '2001', 'Racing', 'Atod', '2', 'Arcade motorcycle racing', 'High-speed drag racing with customization and tuning.', 'Win underground and professional drag races to earn parts.', 'A specialized racing game focused on acceleration and timing.', 'Dragstars brings the thrill of the 1/4 mile to PS1. Fine-tune your engine and time your shifts perfectly to dominate the drag strip.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dreams-to-reality', 'Playstation', 'Dreams to Reality', '1997', 'Adventure', 'Psygnosis', '1', 'Cinematic adventure', 'Surreal third-person action-adventure with flight mechanics.', 'Navigate a dream world to stop a cosmic threat from reality.', 'A visually unique and abstract adventure with a vast scale.', 'Dreams to Reality offers a surreal journey through the subconscious. Fly, swim, and fight through imaginative landscapes in this experimental title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driver-2:-back-on-the-streets', 'Playstation', 'Driver 2: Back on the Streets', '2000', 'Action', 'Reflections Interactive', '2', 'Open-world driving', 'Mission-based driving and action in vast open-world cities.', 'Infiltrate a criminal organization across Chicago, Havana, Vegas, and Rio.', 'A cinematic driving sequel with the ability to step out of the car.', 'Driver 2: Back on the Streets doubles the action. Explore massive cities, switch vehicles, and outrun the law in this ambitious crime thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('driver:-you-are-the-wheelman', 'Playstation', 'Driver: You Are the Wheelman', '1999', 'Action', 'Reflections Interactive', '2', 'Open-world driving', 'Mission-based driving game focusing on high-speed chases.', 'Complete high-stakes jobs as a getaway driver for the mob.', 'A revolutionary title that defined the cinematic driving genre.', 'Driver: You Are the Wheelman features realistic car physics and a gritty 70s vibe. Master the stunt course and survive the most intense police pursuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ducati-world-racing-challenge', 'Playstation', 'Ducati World Racing Challenge', '2001', 'Racing', 'Attention to Detail', '2', 'Motorcycle racing simulation', 'Realistic motorcycle racing featuring licensed Ducati bikes.', 'Win championships and unlock the history of the Ducati brand.', 'A comprehensive bike sim covering vintage and modern models.', 'Ducati World Racing Challenge offers authentic handling and detailed tracks. Climb the ranks from classic bikes to modern superbikes in this licensed racer.');